(defn ml_find_line ^S_block_hdr [^Editor ed ^S_file_buffer buf ^long lnum ^long action]
  (loop [st 0
         ^S_file_buffer buf buf
         lnum lnum
         action action
         ^S_pointer_block pp nil
         ^S_info_pointer ip nil
         ^S_block_hdr bp nil
         low 0
         high 0
         top 0
         idx 0]
    (case st
      0
      (if (nil? (.ml_locked ^S_memline (.-b_ml buf)))
        (recur 1 buf lnum action pp ip bp low high top idx)
        (if (and (and (not (zero? (bit-and action 16))) (<= (.ml_locked_low ^S_memline (.-b_ml buf)) lnum)) (>= (.ml_locked_high ^S_memline (.-b_ml buf)) lnum))
          (if (== action (e ML_INSERT))
            (let [_ (.set_ml_locked_lineadd ^S_memline (.-b_ml buf) (i32 (inc (.ml_locked_lineadd ^S_memline (.-b_ml buf)))))
                  _ (.set_ml_locked_high ^S_memline (.-b_ml buf) (inc (.ml_locked_high ^S_memline (.-b_ml buf))))]
              (.ml_locked ^S_memline (.-b_ml buf)))
            (if (== action (e ML_DELETE))
              (let [_ (.set_ml_locked_lineadd ^S_memline (.-b_ml buf) (i32 (dec (.ml_locked_lineadd ^S_memline (.-b_ml buf)))))
                    _ (.set_ml_locked_high ^S_memline (.-b_ml buf) (dec (.ml_locked_high ^S_memline (.-b_ml buf))))]
                (.ml_locked ^S_memline (.-b_ml buf)))
              (.ml_locked ^S_memline (.-b_ml buf))))
          (let [_ (.set_ml_locked ^S_memline (.-b_ml buf) nil)]
