                (recur 1 buf lnum action pp ip bp low high top idx))))))
      1
      (if (== action (e ML_FLUSH))
        nil
        (let [^S_block_hdr bp (.ml_root ^S_memline (.-b_ml buf))
              low 1
              high (.ml_line_count ^S_memline (.-b_ml buf))]
          (if (== action (e ML_FIND))
            (let [top (i32 (- (.ml_stack_top ^S_memline (.-b_ml buf)) 1))]
              (recur 2 buf lnum action pp ip bp low high top idx))
            (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) 0)]
              (recur 4 buf lnum action pp ip bp low high top idx)))))
      2
      (if (>= top 0)
        (let [^S_info_pointer ip (Ptr/ref (.add ^Ptr (.ml_stack ^S_memline (.-b_ml buf)) top))]
          (if (and (<= (.ip_low ip) lnum) (>= (.ip_high ip) lnum))
