        (recur 3 buf lnum action pp ip bp low high top idx))
      3
      (if (< top 0)
        (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) 0)]
          (recur 4 buf lnum action pp ip bp low high top idx))
        (recur 4 buf lnum action pp ip bp low high top idx))
      4
      (let [^S_block_hdr hp bp]
        (let [high (if (== action (e ML_INSERT))
                    (let [high (inc high)]
                      high)
                    (if (== action (e ML_DELETE))
                      (let [high (dec high)]
                        high)
                      high))]
          (if (== (.bh_id hp) 25697)
            (let [_ (.set_ml_locked ^S_memline (.-b_ml buf) hp)
                  _ (.set_ml_locked_low ^S_memline (.-b_ml buf) low)
                  _ (.set_ml_locked_high ^S_memline (.-b_ml buf) high)
                  _ (.set_ml_locked_lineadd ^S_memline (.-b_ml buf) 0)]
              hp)
            (let [^S_pointer_block pp (.bh_ptr hp)]
              (if (== (.bh_id hp) 28788)
                (let [top (long (ml_add_stack ed buf))]
                  (if (< top 0)
                    (recur 7 buf lnum action pp ip bp low high top idx)
                    (let [^S_info_pointer ip (Ptr/ref (.add ^Ptr (.ml_stack ^S_memline (.-b_ml buf)) top))
                          _ (.set_ip_block ip bp)
                          _ (.set_ip_low ip low)
                          _ (.set_ip_high ip high)
                          _ (.set_ip_index ip -1)
                          idx 0]
                      (recur 5 buf lnum action pp ip bp low high top idx))))
                (let [_ (iemsg ed (BytePtr. (g ed e_pointer_block_id_wrong) 0))]
                  (recur 7 buf lnum action pp ip bp low high top idx)))))))
      5
      (if (< idx (.pb_count pp))
        (let [t (.pe_line_count ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx))
              low (+ low t)]
          (if (> low lnum)
            (let [_ (.set_ip_index ip idx)
                  ^S_block_hdr bp (.pe_block ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx))
                  high (- low 1)
                  low (- low t)]
              (recur 6 buf lnum action pp ip bp low high top idx))
            (let [idx (i32 (inc idx))]
              (recur 5 buf lnum action pp ip bp low high top idx))))
        (recur 6 buf lnum action pp ip bp low high top idx))
      6
      (if (>= idx (.pb_count pp))
        (if (> lnum (.ml_line_count ^S_memline (.-b_ml buf)))
          (let [_ (long (whim.cljhost/vim_snprintf ed (g ed IObuff) (long (emsg_iobuff_room ed)) (BytePtr. (g ed e_line_number_out_of_range_nr_past_the_end) 0) (object-array [(Long/valueOf (- lnum (.ml_line_count ^S_memline (.-b_ml buf))))])))
                _ (iemsg ed (iobuff_or ed (BytePtr. (g ed e_line_number_out_of_range_nr_past_the_end) 0)))]
            (recur 7 buf lnum action pp ip bp low high top idx))
          (let [_ (iemsg ed (BytePtr. (g ed e_line_count_wrong_in_block) 0))]
            (recur 7 buf lnum action pp ip bp low high top idx)))
        (if (== action (e ML_DELETE))
          (let [_ (.set_pe_line_count ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx) (dec (.pe_line_count ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx))))]
            (recur 4 buf lnum action pp ip bp low high top idx))
          (if (== action (e ML_INSERT))
            (let [_ (.set_pe_line_count ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx) (inc (.pe_line_count ^S_pointer_entry (aget ^objects (.-pb_pointer pp) idx))))]
              (recur 4 buf lnum action pp ip bp low high top idx))
            (recur 4 buf lnum action pp ip bp low high top idx))))
      7
      (if (== action (e ML_DELETE))
        (let [_ (ml_lineadd ed buf 1)]
          (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) 0)]
            nil))
        (if (== action (e ML_INSERT))
          (let [_ (ml_lineadd ed buf -1)]
            (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) 0)]
              nil))
          (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) 0)]
            nil)))
      (throw (IllegalStateException. "no state")))))

