(defn intable [^Editor ed ^Ptr table ^long size ^long c]
  (loop [st 0
         ^Ptr table table
         size size
         c c
         bot 0
         top 0]
    (case st
      0
      (if (< c (.first_ ^S_interval (.at table 0)))
        false
        (let [bot 0
              top (i32 (- (Long/divideUnsigned size 16) 1))]
          (recur 1 table size c bot top)))
      1
      (if (>= top bot)
        (let [mid (i32 (quot (i32 (+ bot top)) 2))]
          (if (< (.last_ ^S_interval (.at table mid)) c)
            (let [bot (i32 (+ mid 1))]
              (recur 2 table size c bot top))
            (if (> (.first_ ^S_interval (.at table mid)) c)
              (let [top (i32 (- mid 1))]
                (recur 2 table size c bot top))
              true)))
        false)
      2
      (recur 1 table size c bot top)
      (throw (IllegalStateException. "no state")))))

