                    (loop []
                      (let [_ (aset len 0 (unchecked-int (i32 (+ (long (aget len 0)) (long (aget cc_len 0))))))]
                        (if (< (bit-and (.at p (long (aget len 0))) 0xff) 128)
                          (long (aget len 0))
                          (let [cc (long (utf_ptr2char_and_len ed (.add p (long (aget len 0))) (IntPtr. cc_len 0)))]
