        j (long (termcode_star ed (.code ^S_termcode (.at (g ed termcodes) idx)) (.len ^S_termcode (.at (g ed termcodes) idx))))]
    (if (<= j 0)
      nil
      (let [_ (.set_modlen ^S_termcode (.at (g ed termcodes) idx) (i32 (- (i32 (- (.len ^S_termcode (.at (g ed termcodes) idx)) 1)) j)))]
        (if (== (bit-and (.at ^BytePtr (.code ^S_termcode (.at (g ed termcodes) idx)) (i32 (- (.modlen ^S_termcode (.at (g ed termcodes) idx)) 1))) 0xff) 64)
          (let [_ (.set_modlen ^S_termcode (.at (g ed termcodes) idx) (i32 (dec (.modlen ^S_termcode (.at (g ed termcodes) idx)))))]
            nil)
          nil)))))

