(defn key_name_bsearch ^Ptr [^Editor ed ^S_key_name_entry key_ ^Ptr base nel ^clojure.lang.IFn cmp]
  (let [nel (long nel)]
    (loop [st 0
           ^S_key_name_entry key_ key_
           ^Ptr base base
           nel nel
           ^clojure.lang.IFn cmp cmp]
      (case st
        0
        (recur 1 key_ base nel cmp)
        1
        (if (> (Long/compareUnsigned nel 0) 0)
          (let [^Ptr tryp (.add base (Long/divideUnsigned nel 2))
                sign (long (cmp ed key_ (Ptr/ref tryp)))]
            (if (< sign 0)
              (let [nel (Long/divideUnsigned nel 2)]
                (recur 2 key_ base nel cmp))
              (if (> sign 0)
                (let [^Ptr base (.add tryp 1)
                      nel (- nel (+ (Long/divideUnsigned nel 2) 1))]
                  (recur 2 key_ base nel cmp))
                tryp)))
          nil)
        2
        (recur 1 key_ base nel cmp)
        (throw (IllegalStateException. "no state"))))))

