(defn utf_isupper [^Editor ed ^long a]
  (not (== (long (utf_tolower ed a)) a)))

(defn vim_isupper [^Editor ed ^long c]
  (if (<= c 64)
    false
    (if (>= c 128)
      (utf_isupper ed c)
      (musl_isupper ed (u8 c)))))

(defn musl_towupper ^long [^Editor ed ^long a]
  (long (utf_convert ed a (Ptr. (g ed toUpper) 0) 3184)))

(defn utf_toupper ^long [^Editor ed ^long a]
  (if (and (< a 128) (not (zero? (bit-and (bit-and (aget (g ed cmp_flags) 0) 0xffffffff) (e CMP_KEEPASCII)))))
    (if (or (< a 97) (> a 122)) a (i32 (- a 32)))
    (if (zero? (bit-and (bit-and (aget (g ed cmp_flags) 0) 0xffffffff) (e CMP_INTERNAL)))
      (long (musl_towupper ed a))
      (if (< a 128)
        (long (musl_toupper ed (u8 a)))
        (long (utf_convert ed a (Ptr. (g ed toUpper) 0) 3184))))))

(defn utf_islower [^Editor ed ^long a]
  (or (not (== (long (utf_toupper ed a)) a)) (== a 223)))

(defn vim_islower [^Editor ed ^long c]
  (if (<= c 64)
    false
    (if (>= c 128)
      (utf_islower ed c)
      (musl_islower ed (u8 c)))))

(defn parse_isopt [^Editor ed ^BytePtr var_ ^S_file_buffer buf only_check]
  (let [^objects p (object-array 1)]
    (loop [st 0
           ^BytePtr var_ var_
           ^S_file_buffer buf buf
           only_check only_check
           c 0
           c2 0
           tilde false
           do_isalpha false]
      (case st
        0
        (let [_ (aset p 0 var_)]
          (recur 1 var_ buf only_check c c2 tilde do_isalpha))
        1
        (if (zero? (bit-and (.get ^BytePtr (aget p 0)) 0xff))
          true
          (let [tilde false
                do_isalpha false]
            (let [tilde (if (and (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) 94) (not (== (bit-and (.at ^BytePtr (aget p 0) 1) 0xff) (e NUL))))
                         (let [tilde true
                               _ (aset p 0 (.add ^BytePtr (aget p 0) 1))]
                           tilde)
                         tilde)]
              (let [c (if (< (u32 (- (bit-and (.get ^BytePtr (aget p 0)) 0xff) 48)) 10)
                       (let [c (i32 (long (getdigits ed (Ptr. p 0))))]
                         c)
                       (let [c (long (mb_ptr2char_adv ed (Ptr. p 0)))]
                         c))]
                (let [c2 -1]
                  (let [c2 (if (and (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) 45) (not (== (bit-and (.at ^BytePtr (aget p 0) 1) 0xff) (e NUL))))
                            (let [_ (aset p 0 (.add ^BytePtr (aget p 0) 1))]
                              (if (< (u32 (- (bit-and (.get ^BytePtr (aget p 0)) 0xff) 48)) 10)
                                (let [c2 (i32 (long (getdigits ed (Ptr. p 0))))]
                                  c2)
                                (let [c2 (long (mb_ptr2char_adv ed (Ptr. p 0)))]
                                  c2)))
                            c2)]
                    (if (or (or (or (or (<= c 0) (>= c 256)) (and (< c2 c) (not (== c2 -1)))) (>= c2 256)) (not (or (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) (e NUL)) (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) 44))))
                      false
                      (let [trail_comma (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) 44)
                            _ (aset p 0 (skip_to_option_part ed (aget p 0)))]
                        (if (and trail_comma (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) (e NUL)))
                          false
                          (if only_check
                            (recur 1 var_ buf only_check c c2 tilde do_isalpha)
                            (if (== c2 -1)
                              (if (== c 64)
                                (let [do_isalpha true
                                      c 1
                                      c2 255]
                                  (recur 2 var_ buf only_check c c2 tilde do_isalpha))
                                (let [c2 c]
                                  (recur 2 var_ buf only_check c c2 tilde do_isalpha)))
                              (recur 2 var_ buf only_check c c2 tilde do_isalpha))))))))))))
        2
        (recur 3 var_ buf only_check c c2 tilde do_isalpha)
        3
        (if (<= c c2)
          (do (if (or (or (not do_isalpha) (vim_islower ed c)) (vim_isupper ed c))
                (if (BytePtr/eq var_ ^BytePtr (aget (g ed p_isi) 0))
                  (if tilde
                    (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-and (bit-and (aget (g ed g_chartab) c) 0xff) -33))))]
                      nil)
                    (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-or (bit-and (aget (g ed g_chartab) c) 0xff) (e CT_ID_CHAR)))))]
                      nil))
                  (if (BytePtr/eq var_ ^BytePtr (aget (g ed p_isp) 0))
                    (if (or (< c 32) (> c 126))
                      (if tilde
                        (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (i32 (+ (bit-and (bit-and (aget (g ed g_chartab) c) 0xff) -8) (if (zero? (bit-and (bit-and (aget (g ed dy_flags) 0) 0xffffffff) (e DY_UHEX))) 2 4))))))
                              _ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-and (bit-and (aget (g ed g_chartab) c) 0xff) -17))))]
                          nil)
                        (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (i32 (+ (bit-and (bit-and (aget (g ed g_chartab) c) 0xff) -8) 1)))))
                              _ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-or (bit-and (aget (g ed g_chartab) c) 0xff) (e CT_PRINT_CHAR)))))]
                          nil))
                      nil)
                    (if (BytePtr/eq var_ ^BytePtr (aget (g ed p_isf) 0))
                      (if tilde
                        (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-and (bit-and (aget (g ed g_chartab) c) 0xff) -65))))]
                          nil)
                        (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-or (bit-and (aget (g ed g_chartab) c) 0xff) (e CT_FNAME_CHAR)))))]
                          nil))
                      (if tilde
                        (let [_ (aset ^bytes (.-b_chartab buf) (bit-shift-right (u32 c) 3) (unchecked-byte (u8 (bit-and (bit-and (aget ^bytes (.-b_chartab buf) (bit-shift-right (u32 c) 3)) 0xff) (bit-not (i32 (bit-shift-left 1 (bit-and c 7))))))))]
                          nil)
                        (let [_ (aset ^bytes (.-b_chartab buf) (bit-shift-right (u32 c) 3) (unchecked-byte (u8 (bit-or (bit-and (aget ^bytes (.-b_chartab buf) (bit-shift-right (u32 c) 3)) 0xff) (i32 (bit-shift-left 1 (bit-and c 7)))))))]
                          nil)))))
                nil)
            (let [c (i32 (inc c))]
              (recur 3 var_ buf only_check c c2 tilde do_isalpha)))
          (recur 1 var_ buf only_check c c2 tilde do_isalpha))
        (throw (IllegalStateException. "no state"))))))

(defn buf_init_chartab [^Editor ed ^S_file_buffer buf global]
  (loop [st 0
         ^S_file_buffer buf buf
         global global
         c 0
         i 0]
    (case st
      0
      (if global
        (let [c 0]
          (recur 1 buf global c i))
        (recur 5 buf global c i))
      1
      (if (< c 32)
        (let [t1 c
              c (i32 (inc c))
              _ (aset (g ed g_chartab) t1 (unchecked-byte (u8 (if (zero? (bit-and (bit-and (aget (g ed dy_flags) 0) 0xffffffff) (e DY_UHEX))) 2 4))))]
          (recur 1 buf global c i))
        (recur 2 buf global c i))
      2
      (if (<= c 126)
        (let [t2 c
              c (i32 (inc c))
              _ (aset (g ed g_chartab) t2 (unchecked-byte 17))]
          (recur 2 buf global c i))
        (recur 3 buf global c i))
      3
      (if (< c 256)
        (let [c (if (>= c 160)
                 (let [t3 c
                       c (i32 (inc c))
                       _ (aset (g ed g_chartab) t3 (unchecked-byte 17))]
                   c)
                 (let [t4 c
                       c (i32 (inc c))
                       _ (aset (g ed g_chartab) t4 (unchecked-byte (u8 (if (zero? (bit-and (bit-and (aget (g ed dy_flags) 0) 0xffffffff) (e DY_UHEX))) 2 4))))]
                   c))]
          (recur 3 buf global c i))
        (let [c 1]
          (recur 4 buf global c i)))
      4
      (if (< c 256)
        (do (if (>= c 160)
              (let [_ (aset (g ed g_chartab) c (unchecked-byte (u8 (bit-or (bit-and (aget (g ed g_chartab) c) 0xff) (e CT_FNAME_CHAR)))))]
                nil)
              nil)
          (let [c (i32 (inc c))]
            (recur 4 buf global c i)))
        (recur 5 buf global c i))
      5
      (let [_ (Rt/memset (BytePtr. ^bytes (.-b_chartab buf) 0) (unchecked-int 0) 32)
            i (if global 0 3)]
        (recur 6 buf global c i))
      6
      (if (<= i 3)
        (let [^BytePtr p (if (== i 0)
                          (let [^BytePtr p (aget (g ed p_isi) 0)]
                            p)
                          (if (== i 1)
                            (let [^BytePtr p (aget (g ed p_isp) 0)]
                              p)
                            (if (== i 2)
                              (let [^BytePtr p (aget (g ed p_isf) 0)]
                                p)
                              (let [^BytePtr p (aget ^objects (.-b_p_isk buf) 0)]
                                p))))]
          (if (parse_isopt ed p buf false)
            (let [i (i32 (inc i))]
              (recur 6 buf global c i))
            false))
        (let [_ (g! ed chartab_initialized (e TRUE))]
          true))
      (throw (IllegalStateException. "no state")))))

(defn init_chartab [^Editor ed]
  (buf_init_chartab ed (g ed curbuf) true))

(defn get_highlight_default ^BytePtr [^Editor ed]
  (let [i (long (findoption ed (BytePtr/lit "hl")))]
    (if (>= i 0)
      (aget ^objects (.-def_str ^S_vimoption (aget (g ed options) i)) (e VI_DEFAULT))
      nil)))

(defn vim_strup [^Editor ed ^BytePtr p]
  (if (nil? p)
    nil
    (let [^BytePtr p2 p]
      (loop [^BytePtr p2 p2]
        (let [c (bit-and (.get p2) 0xff)]
          (if (== c (e NUL))
            nil
            (let [^BytePtr t1 p2
                  ^BytePtr p2 (.add p2 1)
                  _ (.put t1 (unchecked-byte (u8 (if (or (< c 97) (> c 122)) c (i32 (- c 32))))))]
              (recur p2))))))))

(defn syn_name2id_len ^long [^Editor ed ^BytePtr name_ ^long len]
  (let [^bytes name_u (byte-array 201)]
    (let [len (if (> len (e MAX_SYN_NAME))
               (let [len (e MAX_SYN_NAME)]
                 len)
               len)]
      (let [_ (Rt/memmove (BytePtr. name_u 0) name_ len)
            _ (aset name_u len (unchecked-byte (e NUL)))
            _ (vim_strup ed (BytePtr. name_u 0))
            i 0]
        (loop [i i]
          (if (< i (.ga_len (g ed highlight_ga)))
            (if (== (long (musl_strcmp ed (.sg_name_u ^T_hl_group_T (.at (GA_Ptr_T_hl_group_T (g ed highlight_ga)) i)) (BytePtr. name_u 0))) 0)
              (i32 (+ i 1))
              (let [i (i32 (inc i))]
                (recur i)))
            0))))))

(defn other_sourcing_name [^Editor ed]
  (if (and (and (some? (.ga_data (g ed exestack))) (> (.ga_len (g ed exestack)) 0)) (some? (.es_name ^T_estack_T (.at (GA_Ptr_T_estack_T (g ed exestack)) (i32 (- (.ga_len (g ed exestack)) 1))))))
    (if (some? (g ed last_sourcing_name))
      (not (== (long (musl_strcmp ed (.es_name ^T_estack_T (.at (GA_Ptr_T_estack_T (g ed exestack)) (i32 (- (.ga_len (g ed exestack)) 1)))) (g ed last_sourcing_name))) 0))
      true)
    false))

(defn estack_sfile ^BytePtr [^Editor ed ^long which]
  (let [^T_estack_T entry (Ptr/ref (.add (.add (GA_Ptr_T_estack_T (g ed exestack)) (.ga_len (g ed exestack))) (- 1)))]
    (if (nil? (.es_name entry))
      nil
      (vim_strsave ed (.es_name entry)))))

(defn get_emsg_source ^BytePtr [^Editor ed]
  (if (and (and (and (some? (.ga_data (g ed exestack))) (> (.ga_len (g ed exestack)) 0)) (some? (.es_name ^T_estack_T (.at (GA_Ptr_T_estack_T (g ed exestack)) (i32 (- (.ga_len (g ed exestack)) 1)))))) (other_sourcing_name ed))
    (let [^BytePtr sname (estack_sfile ed (e ESTACK_NONE))]
      (let [^BytePtr sname (if (nil? sname)
                            (let [^BytePtr sname (.es_name ^T_estack_T (.at (GA_Ptr_T_estack_T (g ed exestack)) (i32 (- (.ga_len (g ed exestack)) 1))))]
                              sname)
                            sname)]
        (let [^BytePtr p (gettext_ ed (BytePtr/lit "Error detected while processing %s:"))
              ^BytePtr Buf (BytePtr/alloc (+ (long (musl_strlen ed sname)) (long (musl_strlen ed p))))
              _ (long (whim.cljhost/vim_snprintf ed Buf (+ (long (musl_strlen ed sname)) (long (musl_strlen ed p))) p (object-array [sname])))]
          Buf)))
    nil))

(defn reg_getline_common [^Editor ed lnum flags ^Ptr line ^IntPtr length]
  (let [lnum (long lnum)
        flags (long flags)]
    (let [get_line (bit-and flags (e RGLF_LINE))
          get_length (bit-and flags (e RGLF_LENGTH))
          firstlnum (+ (.reg_firstlnum (g ed rex)) lnum)
          maxline (.reg_maxline (g ed rex))]
      (if (< firstlnum 1)
        (do (if (zero? get_line)
              nil
              (let [_ (.put line nil)]
                nil))
          (if (zero? get_length)
            nil
            (let [_ (.put length (unchecked-int 0))]
              nil)))
        (if (> lnum maxline)
          (do (if (zero? get_line)
                nil
                (let [_ (.put line (BytePtr/lit ""))]
                  nil))
            (if (zero? get_length)
              nil
              (let [_ (.put length (unchecked-int 0))]
                nil)))
          (do (if (zero? get_line)
                nil
                (let [_ (.put line (ml_get_buf ed (.reg_buf (g ed rex)) firstlnum false))]
                  nil))
            (if (zero? get_length)
              nil
              (let [_ (.put length (unchecked-int (long (ml_get_buf_len ed (.reg_buf (g ed rex)) firstlnum))))]
                nil))))))))

(defn reg_getline ^BytePtr [^Editor ed ^long lnum]
  (let [^objects line (object-array 1)]
    (let [_ (reg_getline_common ed lnum (e RGLF_LINE) (Ptr. line 0) nil)]
      (aget line 0))))

(defn prog_magic_wrong [^Editor ed]
  (let [^S_regprog prog (if (nil? (.reg_match (g ed rex))) (.regprog ^T_regmmatch_T (.reg_mmatch (g ed rex))) (.regprog ^T_regmatch_T (.reg_match (g ed rex))))]
    (if (== (bit-and (.get ^BytePtr (.program prog)) 0xff) (e REGMAGIC))
      false
      (let [_ (iemsg ed (BytePtr. (g ed e_corrupted_regexp_program) 0))]
        true))))

(defn utf_safe_read_char_adv ^long [^Editor ed ^Ptr s ^LongPtr n]
  (if (== (.get n) 0)
    0
    (let [k (long (aget (g ed utf8len_tab_zero) (bit-and (.get ^BytePtr (.get s)) 0xff)))]
      (if (== k 1)
        (let [_ (.put n (dec (.get n)))
              ^BytePtr t1 (.get s)
              _ (.put s (.add ^BytePtr (.get s) 1))]
          (bit-and (.get t1) 0xff))
        (if (<= (Long/compareUnsigned k (.get n)) 0)
          (let [c (long (utf_ptr2char ed (.get s)))]
            (if (or (not (== c (bit-and (.get ^BytePtr (.get s)) 0xff))) (and (== c 195) (== (bit-and (.at ^BytePtr (.get s) 1) 0xff) 131)))
              (let [_ (.put s (.add ^BytePtr (.get s) k))
                    _ (.put n (- (.get n) k))]
                c)
              -1))
          -1)))))

(defn utf_fold ^long [^Editor ed ^long a]
  (if (< a 128)
    (if (and (>= a 65) (<= a 90)) (i32 (+ a 32)) a)
    (long (utf_convert ed a (Ptr. (g ed foldCase) 0) 3296))))

(defn utf_strnicmp [^Editor ed ^BytePtr s1__1 ^BytePtr s2__2 n1__3 n2__4]
  (let [^objects s1 (doto (object-array 1) (aset 0 s1__1))
        ^objects s2 (doto (object-array 1) (aset 0 s2__2))
        ^longs n1 (doto (long-array 1) (aset 0 (long n1__3)))
        ^longs n2 (doto (long-array 1) (aset 0 (long n2__4)))
        ^bytes buffer (byte-array 6)]
    (loop []
      (let [c1 (long (utf_safe_read_char_adv ed (Ptr. s1 0) (LongPtr. n1 0)))
            c2 (long (utf_safe_read_char_adv ed (Ptr. s2 0) (LongPtr. n2 0)))]
        (if (or (<= c1 0) (<= c2 0))
          (if (or (== c1 0) (== c2 0))
            (if (and (== c1 0) (== c2 0))
              0
              (if (== c1 0) -1 1))
            (do (if (and (not (== c1 -1)) (== c2 -1))
                  (let [_ (aset n1 0 (long (utf_char2bytes ed (long (utf_fold ed c1)) (BytePtr. buffer 0))))
                        _ (aset s1 0 (BytePtr. buffer 0))]
                    nil)
                  (if (and (not (== c2 -1)) (== c1 -1))
                    (let [_ (aset n2 0 (long (utf_char2bytes ed (long (utf_fold ed c2)) (BytePtr. buffer 0))))
                          _ (aset s2 0 (BytePtr. buffer 0))]
                      nil)
                    nil))
              (loop []
                (if (and (and (and (> (Long/compareUnsigned (aget n1 0) 0) 0) (> (Long/compareUnsigned (aget n2 0) 0) 0)) (not (== (bit-and (.get ^BytePtr (aget s1 0)) 0xff) (e NUL)))) (not (== (bit-and (.get ^BytePtr (aget s2 0)) 0xff) (e NUL))))
                  (let [cdiff (i32 (- (bit-and (.get ^BytePtr (aget s1 0)) 0xff) (bit-and (.get ^BytePtr (aget s2 0)) 0xff)))]
                    (if (== cdiff 0)
                      (let [_ (aset s1 0 (.add ^BytePtr (aget s1 0) 1))
                            _ (aset s2 0 (.add ^BytePtr (aget s2 0) 1))
                            _ (aset n1 0 (dec (aget n1 0)))
                            _ (aset n2 0 (dec (aget n2 0)))]
                        (recur))
                      cdiff))
                  (do (if (and (> (Long/compareUnsigned (aget n1 0) 0) 0) (== (bit-and (.get ^BytePtr (aget s1 0)) 0xff) (e NUL)))
                        (let [_ (aset n1 0 0)]
                          nil)
                        nil)
                    (do (if (and (> (Long/compareUnsigned (aget n2 0) 0) 0) (== (bit-and (.get ^BytePtr (aget s2 0)) 0xff) (e NUL)))
                          (let [_ (aset n2 0 0)]
                            nil)
                          nil)
                      (if (and (== (aget n1 0) 0) (== (aget n2 0) 0))
                        0
                        (if (== (aget n1 0) 0) -1 1))))))))
          (if (== c1 c2)
            (recur)
            (let [cdiff (i32 (- (long (utf_fold ed c1)) (long (utf_fold ed c2))))]
              (if (== cdiff 0)
                (recur)
                cdiff))))))))

(defn mb_strnicmp ^long [^Editor ed ^BytePtr s1 ^BytePtr s2 ^long nn]
  (long (utf_strnicmp ed s1 s2 nn nn)))

(defn mb_strnicmp2 [^Editor ed ^BytePtr s1 ^BytePtr s2 n1 n2]
  (let [n1 (long n1)
        n2 (long n2)]
    (if (== n1 n2)
      (long (mb_strnicmp ed s1 s2 n1))
      (long (utf_strnicmp ed s1 s2 n1 n2)))))

(defn mb_decompose [^Editor ed c ^IntPtr c1 ^IntPtr c2 ^IntPtr c3]
  (let [c (long c)
        ^T_decomp_T d (new-T_decomp_T)]
    (if (and (>= c 64288) (<= c 64335))
      (let [_ (.set d (aget (g ed decomp_table) (i32 (- c 64288))))
            _ (.put c1 (unchecked-int (.a d)))
            _ (.put c2 (unchecked-int (.b d)))
            _ (.put c3 (unchecked-int (.c d)))]
        nil)
      (let [_ (.put c1 (unchecked-int c))
            _ (.put c2 (unchecked-int 0))
            _ (.put c3 (unchecked-int 0))]
        nil))))

(defn cstrncmp ^long [^Editor ed ^BytePtr s1 ^BytePtr s2 ^IntPtr n]
  (let [^objects str1 (object-array 1)
        ^objects str2 (object-array 1)
        ^ints c11 (int-array 1)
        ^ints c12 (int-array 1)
        ^ints junk (int-array 1)]
    (loop [st 0
           ^BytePtr s1 s1
           ^BytePtr s2 s2
           ^IntPtr n n
           result 0
           ^BytePtr p nil
           n2 0
           n1 0
           c1 0
           c2 0]
