          result)
        4
        (if (< (i32 (.sub ^BytePtr (aget str1 0) s1)) (long (.get n)))
          (let [c1 (long (mb_ptr2char_adv ed (Ptr. str1 0)))
                c2 (long (mb_ptr2char_adv ed (Ptr. str2 0)))]
            (if (and (not (== c1 c2)) (or (zero? (.reg_ic (g ed rex))) (not (== (long (utf_fold ed c1)) (long (utf_fold ed c2))))))
              (let [_ (mb_decompose ed c1 (IntPtr. c11 0) (IntPtr. junk 0) (IntPtr. junk 0))
                    _ (mb_decompose ed c2 (IntPtr. c12 0) (IntPtr. junk 0) (IntPtr. junk 0))
