      (let [^LongPtr flagsp_local (if both
                                   (let [^LongPtr flagsp_local (LongPtr. ^longs (.-flags ^S_vimoption (aget (g ed options) opt_idx)) 0)]
                                     flagsp_local)
                                   flagsp_local)]
        (if (and (zero? value_checked) (not (zero? (g ed secure))))
          (let [_ (.put flagsp (bit-or (.get flagsp) (e P_INSECURE)))]
            (if (some? flagsp_local)
