(defn out_str_nf [^Editor ed ^BytePtr s]
  (do (if (> (g ed out_pos) 8111)
        (let [_ (out_flush ed)]
          nil)
        nil)
    (let [^BytePtr p s]
      (loop [^BytePtr p p]
        (if (== (bit-and (.get p) 0xff) (e NUL))
          (if (zero? (aget (g ed p_wd) 0))
            nil
            (let [_ (out_flush ed)]
              nil))
          (let [_ (long (out_char_nf ed (bit-and (.get p) 0xff)))]
            (let [^BytePtr p (.add p 1)]
              (recur p))))))))

(defn term_set_sync_output [^Editor ed ^long flags]
  (let [in_gui false
        allowed (and (not (zero? (long (aget (g ed p_tsy) 0)))) (or (== (g ed sync_output_setting) 1) (== (g ed sync_output_setting) 2)))]
    (if (zero? (bit-and flags (e TERM_SYNC_OUTPUT_FLUSH)))
      (if (zero? (bit-and flags (e TERM_SYNC_OUTPUT_OFF)))
        (if (or (or (or (not allowed) in_gui) (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 92)) 0xff) (e NUL))) (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 93)) 0xff) (e NUL)))
          nil
          (if (zero? (bit-and flags (e TERM_SYNC_OUTPUT_ENABLE)))
            (if (zero? (bit-and flags (e TERM_SYNC_OUTPUT_DISABLE)))
              (let [_ (long (whim.cljhost/vim_snprintf ed (g ed IObuff) (long (emsg_iobuff_room ed)) (BytePtr/lit "Unknown sync output value %d") (object-array [(Integer/valueOf (unchecked-int flags))])))
                    _ (iemsg ed (iobuff_or ed (BytePtr/lit "Unknown sync output value %d")))]
                nil)
              (let [t2 (== (g ed sync_output_state) 0)]
                (let [t2 (if t2
                          t2
                          (let [_ (g! ed sync_output_state (i32 (dec (g ed sync_output_state))))
                                t2 (> (g ed sync_output_state) 0)]
                            t2))]
                  (if t2
                    nil
                    (let [_ (out_str_nf ed (aget (g ed term_strings) 93))
                          _ (out_flush ed)]
                      nil)))))
            (let [t1 (g ed sync_output_state)
                  _ (g! ed sync_output_state (i32 (inc (g ed sync_output_state))))]
              (if (> t1 0)
                nil
                (let [_ (out_str_nf ed (aget (g ed term_strings) 92))]
                  nil)))))
        (if (and (> (g ed sync_output_state) 0) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 93)) 0xff) (e NUL))))
          (let [_ (out_str_nf ed (aget (g ed term_strings) 93))
                _ (out_flush ed)
                _ (g! ed sync_output_state 0)]
            nil)
          nil))
      (if (and (and (and (and allowed (not in_gui)) (> (g ed sync_output_state) 0)) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 93)) 0xff) (e NUL)))) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 92)) 0xff) (e NUL))))
        (let [_ (out_str_nf ed (aget (g ed term_strings) 93))
              _ (out_str_nf ed (aget (g ed term_strings) 92))
              _ (out_flush ed)]
          nil)
        nil))))

