(defn linecopy [^Editor ed ^long to ^long from ^S_window_S wp]
  (let [off_to (u32 (+ (bit-and (.at (g ed LineOffset) to) 0xffffffff) (u32 (.w_wincol wp))))
        off_from (u32 (+ (bit-and (.at (g ed LineOffset) from) 0xffffffff) (u32 (.w_wincol wp))))
        _ (Rt/memmove (.add (g ed ScreenLines) off_to) (.add (g ed ScreenLines) off_from) (* (.w_width wp) 1))
        _ (Rt/memmove (.add (g ed ScreenLinesUC) off_to) (.add (g ed ScreenLinesUC) off_from) (.w_width wp))
        i 0]
    (loop [i i]
      (if (< i (aget (g ed p_mco) 0))
        (let [_ (Rt/memmove (.add ^IntPtr (aget (g ed ScreenLinesC) i) off_to) (.add ^IntPtr (aget (g ed ScreenLinesC) i) off_from) (.w_width wp))]
          (let [i (i32 (inc i))]
            (recur i)))
        (let [_ (Rt/memmove (.add (g ed ScreenAttrs) off_to) (.add (g ed ScreenAttrs) off_from) (.w_width wp))
              _ (Rt/memmove (.add (g ed ScreenCols) off_to) (.add (g ed ScreenCols) off_from) (.w_width wp))]
          nil)))))

(defn screen_draw_rectangle [^Editor ed row col height width invert]
  (let [row (long row)
        col (long col)
        height (long height)
        width (long width)]
    (if (nil? (g ed ScreenLines))
      nil
      (do (if invert
            (let [_ (g! ed screen_char_attr (e HL_INVERSE))]
              nil)
            nil)
        (let [r row]
          (loop [r r]
            (if (< r (i32 (+ row height)))
              (let [off (i32 (bit-and (.at (g ed LineOffset) r) 0xffffffff))
                    max_off (i32 (+ off (g ed screen_Columns)))
                    c col]
                (do (loop [c c]
                      (if (< c (i32 (+ col width)))
                        (let [_ (screen_char ed (u32 (i32 (+ off c))) r c)]
                          (let [c (if (> (long (utf_off2cells ed (u32 (i32 (+ off c))) (u32 max_off))) 1)
                                   (let [c (i32 (inc c))]
                                     c)
                                   c)]
                            (let [c (i32 (inc c))]
                              (recur c))))
                        nil))
                  (let [r (i32 (inc r))]
                    (recur r))))
              (let [_ (g! ed screen_char_attr 0)]
                nil))))))))

(defn redraw_block [^Editor ed ^long row ^long end ^S_window_S wp]
