    (let [col (.w_wincol (g ed curwin))
          width (.fr_width (g ed topframe))]
      (let [_ (screen_draw_rectangle ed row col (i32 (- end row)) width false)]
        nil))
    (let [col (.w_wincol wp)
          width (.w_width wp)]
      (let [_ (screen_draw_rectangle ed row col (i32 (- end row)) width false)]
        nil))))

