(defn screen_del_lines [^Editor ed off row line_count end force_ clear_attr ^S_window_S wp]
  (let [off (long off)
        row (long row)
        line_count (long line_count)
        end (long end)
        clear_attr (long clear_attr)]
    (loop [st 0
           off off
           row row
           line_count line_count
           end end
           force_ force_
           clear_attr clear_attr
           ^S_window_S wp wp
           j 0
           i 0
           temp 0
           cursor_row 0
           cursor_col 0
           cursor_end 0
           type_ 0]
      (case st
        0
        (let [cursor_col 0]
          (if (or (or (or (not (screen_valid ed true)) (<= line_count 0)) (and (not force_) (> line_count (aget (g ed p_ttyscroll) 0)))) (> end (aget (g ed Rows) 0)))
            false
