                    (let [type_ (e USE_NL)]
                      (recur 1 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
                    (if (and (and (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 5)) 0xff) (e NUL))) (> line_count 1)) can_delete)
                      (let [type_ (e USE_T_CDL)]
                        (recur 1 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
                      (if (and (and (can_clear ed (aget (g ed term_strings) 1)) result_empty) (or (nil? wp) (== (.w_width wp) (.fr_width (g ed topframe)))))
                        (let [type_ (e USE_T_CE)]
                          (recur 1 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
