                            false))))))))))
        1
        (let [cursor_col (if (and (and (and (some? wp) (not (== (.w_wincol wp) 0))) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 76)) 0xff) (e NUL)))) (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 48)) 0xff) (e NUL)))
                          (let [cursor_col (.w_wincol wp)]
                            cursor_col)
                          cursor_col)]
          (if (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 48)) 0xff) (e NUL))
            (let [cursor_row (i32 (+ row off))
                  cursor_end (i32 (+ end off))]
              (recur 2 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
            (let [cursor_row row
                  cursor_end end]
