            (recur 6 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_)))
        6
        (if (and (not (zero? (bit-and (.get ^BytePtr (aget (g ed term_strings) 11)) 0xff))) (or (== type_ (e USE_T_DL)) (== type_ (e USE_T_CDL))))
          (let [i line_count]
