          true)
        8
        (let [j (i32 (+ j line_count))]
          (if (<= j (i32 (- end 1)))
            (let [_ (.set (g ed LineOffset) (i32 (- j line_count)) (unchecked-int (bit-and (.at (g ed LineOffset) j) 0xffffffff)))
                  _ (.set (g ed LineWraps) (i32 (- j line_count)) (unchecked-byte (bit-and (.at (g ed LineWraps) j) 0xff)))]
              (recur 8 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
            (let [_ (.set (g ed LineOffset) (i32 (- j line_count)) (unchecked-int temp))
                  _ (.set (g ed LineWraps) (i32 (- j line_count)) (unchecked-byte (e FALSE)))]
