                  (recur 10 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
                (let [_ (lineinvalid ed temp (i32 (aget (g ed Columns) 0)))]
                  (recur 10 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))))))
        9
        (let [j (i32 (+ j line_count))]
          (if (<= j (i32 (- end 1)))
            (let [_ (linecopy ed (i32 (- j line_count)) j wp)]
              (recur 9 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))
            (let [j (i32 (- j line_count))]
              (do (if (can_clear ed (BytePtr/lit " "))
                    (let [_ (lineclear ed (u32 (+ (bit-and (.at (g ed LineOffset) j) 0xffffffff) (u32 (.w_wincol wp)))) (.w_width wp) clear_attr)]
                      nil)
                    (let [_ (lineinvalid ed (u32 (+ (bit-and (.at (g ed LineOffset) j) 0xffffffff) (u32 (.w_wincol wp)))) (.w_width wp))]
                      nil))
                (let [_ (.set (g ed LineWraps) j (unchecked-byte (e FALSE)))]
                  (recur 10 off row line_count end force_ clear_attr wp j i temp cursor_row cursor_col cursor_end type_))))))
