                        (if (and can_ce result_empty)
                          (let [type_ (e USE_T_CE)]
                            (recur 1 off row line_count end clear_attr wp i j temp cursor_row cursor_col type_))
                          (if (and (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 4)) 0xff) (e NUL))) result_empty)
                            (let [type_ (e USE_T_DL)]
                              (recur 1 off row line_count end clear_attr wp i j temp cursor_row cursor_col type_))
