                          (recur 1 off row line_count end clear_attr wp i j temp cursor_row cursor_col type_))))))))))
        1
        (if (or (or (or (== type_ (e USE_T_CD)) (== type_ (e USE_T_CDL))) (== type_ (e USE_T_CE))) (== type_ (e USE_T_DL)))
          (screen_del_lines ed off row line_count end false 0 wp)
