            (let [cursor_col (if (and (and (and (some? wp) (not (== (.w_wincol wp) 0))) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 76)) 0xff) (e NUL)))) (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 48)) 0xff) (e NUL)))
                              (let [cursor_col (.w_wincol wp)]
                                cursor_col)
                              cursor_col)]
              (let [cursor_row (if (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 48)) 0xff) (e NUL))
                                (let [cursor_row (i32 (+ row off))]
