        _ (check_string_option ed (Ptr. ^objects (.-wo_lcs wop) 0))
        _ (check_string_option ed (Ptr. ^objects (.-wo_fcs wop) 0))
        _ (check_string_option ed (Ptr. ^objects (.-wo_ve wop) 0))
        _ (check_string_option ed (Ptr. ^objects (.-wo_whl wop) 0))]
    nil))

(defn copy_winopt [^Editor ed ^T_winopt_T from ^T_winopt_T to]
  (let [_ (aset ^ints (.-wo_list to) 0 (unchecked-int (long (aget ^ints (.-wo_list from) 0))))
        _ (aset ^objects (.-wo_lcs to) 0 (copy_option_val ed (aget ^objects (.-wo_lcs from) 0)))
        _ (aset ^objects (.-wo_fcs to) 0 (copy_option_val ed (aget ^objects (.-wo_fcs from) 0)))
        _ (aset ^ints (.-wo_nu to) 0 (unchecked-int (long (aget ^ints (.-wo_nu from) 0))))
        _ (aset ^ints (.-wo_rnu to) 0 (unchecked-int (long (aget ^ints (.-wo_rnu from) 0))))
        _ (aset ^objects (.-wo_ve to) 0 (copy_option_val ed (aget ^objects (.-wo_ve from) 0)))
        _ (aset ^ints (.-wo_ve_flags to) 0 (unchecked-int (bit-and (aget ^ints (.-wo_ve_flags from) 0) 0xffffffff)))
        _ (aset ^ints (.-wo_wrap to) 0 (unchecked-int (long (aget ^ints (.-wo_wrap from) 0))))
        _ (aset ^objects (.-wo_wcr to) 0 (copy_option_val ed (aget ^objects (.-wo_wcr from) 0)))
        _ (aset ^ints (.-wo_sms to) 0 (unchecked-int (long (aget ^ints (.-wo_sms from) 0))))
        _ (aset ^longs (.-wo_siso to) 0 (aget ^longs (.-wo_siso from) 0))
        _ (aset ^longs (.-wo_so to) 0 (aget ^longs (.-wo_so from) 0))
        _ (aset ^longs (.-wo_sop to) 0 (aget ^longs (.-wo_sop from) 0))
        _ (.set_wo_wrap_flags to (.wo_wrap_flags from))
        _ (aset ^objects (.-wo_whl to) 0 (copy_option_val ed (aget ^objects (.-wo_whl from) 0)))
        _ (check_winopt ed to)]
    nil))

(defn buflist_setfpos [^Editor ed ^S_file_buffer buf ^S_window_S win lnum col copy_options]
  (let [lnum (long lnum)
        col (long col)]
    (loop [st 0
           ^S_file_buffer buf buf
           ^S_window_S win win
           lnum lnum
           col col
           copy_options copy_options
           ^S_wininfo_S wip nil]
      (case st
        0
        (let [^S_wininfo_S wip (.b_wininfo buf)]
          (recur 1 buf win lnum col copy_options wip))
        1
        (if (some? wip)
          (if (identical? (.wi_win wip) win)
            (recur 2 buf win lnum col copy_options wip)
            (let [^S_wininfo_S wip (.wi_next wip)]
              (recur 1 buf win lnum col copy_options wip)))
          (recur 2 buf win lnum col copy_options wip))
        2
        (if (nil? wip)
          (let [^S_wininfo_S wip (new-S_wininfo_S)
                _ (.set_wi_win wip win)]
            (if (== lnum 0)
              (let [lnum 1]
                (recur 3 buf win lnum col copy_options wip))
              (recur 3 buf win lnum col copy_options wip)))
          (do (if (nil? (.wi_prev wip))
                (let [_ (.set_b_wininfo buf (.wi_next wip))]
                  nil)
                (let [_ (.set_wi_next ^S_wininfo_S (.wi_prev wip) (.wi_next wip))]
                  nil))
            (do (if (nil? (.wi_next wip))
                  nil
                  (let [_ (.set_wi_prev ^S_wininfo_S (.wi_next wip) (.wi_prev wip))]
                    nil))
              (if (and copy_options (.wi_optset wip))
                (let [_ (clear_winopt ed (.-wi_opt wip))]
                  (recur 3 buf win lnum col copy_options wip))
                (recur 3 buf win lnum col copy_options wip)))))
        3
        (do (if (== lnum 0)
              nil
              (let [_ (aset ^longs (.-lnum ^T_pos_T (.-wi_fpos wip)) 0 lnum)
                    _ (aset ^ints (.-col ^T_pos_T (.-wi_fpos wip)) 0 (unchecked-int col))]
                nil))
          (do (if (and copy_options (some? win))
                (let [_ (copy_winopt ed (.-w_onebuf_opt win) (.-wi_opt wip))
                      _ (.set_wi_optset wip (boolean true))]
                  nil)
                nil)
            (let [_ (.set_wi_next wip (.b_wininfo buf))
                  _ (.set_b_wininfo buf wip)
                  _ (.set_wi_prev wip nil)]
              (if (nil? (.wi_next wip))
                nil
                (let [_ (.set_wi_prev ^S_wininfo_S (.wi_next wip) wip)]
                  nil)))))
        (throw (IllegalStateException. "no state"))))))

(defn may_clear_cmdline [^Editor ed]
  (if (zero? (g ed mode_displayed))
    (let [_ (clear_showcmd ed)]
      nil)
    (let [_ (g! ed clear_cmdline (e TRUE))]
