(defn adjust_cursor_eol [^Editor ed]
  (let [^ints scol (int-array 1)
        ^ints ecol (int-array 1)]
    (let [cur_ve_flags (long (get_ve_flags ed))
          adj_cursor (and (and (and (and (> (long (aget ^ints (.-col ^T_pos_T (.-w_cursor (g ed curwin))) 0)) 0) (== (long (gchar_cursor ed)) (e NUL))) (== (bit-and cur_ve_flags (e VE_ONEMORE)) 0)) (== (bit-and cur_ve_flags (e VE_ALL)) 0)) (not (or (not (zero? (g ed restart_edit))) (not (zero? (bit-and (g ed State) (e MODE_INSERT)))))))]
      (if adj_cursor
        (let [_ (long (dec_cursor ed))]
          (if (== cur_ve_flags (e VE_ALL))
            (let [_ (getvcol ed (g ed curwin) (.-w_cursor (g ed curwin)) (IntPtr. scol 0) nil (IntPtr. ecol 0) 0)
                  _ (.set_coladd ^T_pos_T (.-w_cursor (g ed curwin)) (i32 (+ (i32 (- (long (aget ecol 0)) (long (aget scol 0)))) 1)))]
              nil)
            nil))
        nil))))

(defn end_visual_mode_keep_button [^Editor ed]
  (let [_ (g! ed VIsual_active (e FALSE))
        _ (g! ed mouse_dragging 0)
        _ (.set_vi_mode ^T_visualinfo_T (.-b_visual (g ed curbuf)) (g ed VIsual_mode))
        _ (.set ^T_pos_T (.-vi_start ^T_visualinfo_T (.-b_visual (g ed curbuf))) (g ed VIsual))
        _ (.set ^T_pos_T (.-vi_end ^T_visualinfo_T (.-b_visual (g ed curbuf))) (.-w_cursor (g ed curwin)))
        _ (.set_vi_curswant ^T_visualinfo_T (.-b_visual (g ed curbuf)) (.w_curswant (g ed curwin)))]
    (if (zero? (long (virtual_active ed)))
      (let [_ (.set_coladd ^T_pos_T (.-w_cursor (g ed curwin)) 0)]
        (let [_ (may_clear_cmdline ed)
              _ (adjust_cursor_eol ed)]
