(defn u_freeentry [^Editor ed ^S_u_entry uep ^long n]
  (loop [n n]
    (if (> n 0)
      (let [n (dec n)]
        (recur n))
      nil)))

(defn u_freeentries [^Editor ed ^S_file_buffer buf ^S_u_header uhp ^Ptr uhpp]
  (do (if (identical? (.b_u_curhead buf) uhp)
        (let [_ (.set_b_u_curhead buf nil)]
          nil)
        nil)
    (do (if (identical? (.b_u_newhead buf) uhp)
          (let [_ (.set_b_u_newhead buf nil)]
            nil)
          nil)
      (do (if (and (some? uhpp) (identical? uhp (.get uhpp)))
            (let [_ (.put uhpp nil)]
              nil)
            nil)
        (let [^S_u_entry uep (.uh_entry uhp)]
          (loop [^S_u_entry uep uep]
            (if (some? uep)
              (let [^S_u_entry nuep (.ue_next uep)
                    _ (u_freeentry ed uep (.ue_size uep))]
                (let [^S_u_entry uep nuep]
                  (recur uep)))
              (let [_ (.set_b_u_numhead buf (i32 (dec (.b_u_numhead buf))))]
                nil))))))))

(defn u_freebranch [^Editor ed ^S_file_buffer buf ^S_u_header uhp ^Ptr uhpp]
  (if (identical? uhp (.b_u_oldhead buf))
    (loop []
      (if (some? (.b_u_oldhead buf))
        (let [_ (u_freeheader ed buf (.b_u_oldhead buf) uhpp)]
          (recur))
        nil))
    (do (if (some? (.uh_alt_prev uhp))
          (let [_ (.set_uh_alt_next ^S_u_header (.uh_alt_prev uhp) nil)]
            nil)
          nil)
      (let [^S_u_header next_ uhp]
        (loop [^S_u_header next_ next_]
          (if (some? next_)
            (let [^S_u_header tofree next_]
              (do (if (some? (.uh_alt_next tofree))
                    (let [_ (u_freebranch ed buf (.uh_alt_next tofree) uhpp)]
                      nil)
                    nil)
                (let [^S_u_header next_ (.uh_prev tofree)
                      _ (u_freeentries ed buf tofree uhpp)]
                  (recur next_))))
            nil))))))

(defn u_freeheader [^Editor ed ^S_file_buffer buf ^S_u_header uhp ^Ptr uhpp]
  (do (if (some? (.uh_alt_next uhp))
        (let [_ (u_freebranch ed buf (.uh_alt_next uhp) uhpp)]
          nil)
        nil)
    (do (if (some? (.uh_alt_prev uhp))
          (let [_ (.set_uh_alt_next ^S_u_header (.uh_alt_prev uhp) nil)]
            nil)
          nil)
      (do (if (nil? (.uh_next uhp))
            (let [_ (.set_b_u_oldhead buf (.uh_prev uhp))]
              nil)
            (let [_ (.set_uh_prev ^S_u_header (.uh_next uhp) (.uh_prev uhp))]
              nil))
        (if (nil? (.uh_prev uhp))
          (let [_ (.set_b_u_newhead buf (.uh_next uhp))]
            (let [_ (u_freeentries ed buf uhp uhpp)]
              nil))
          (let [^S_u_header uhap (.uh_prev uhp)]
            (loop [^S_u_header uhap uhap]
              (if (some? uhap)
                (let [_ (.set_uh_next uhap (.uh_next uhp))]
                  (let [^S_u_header uhap (.uh_alt_next uhap)]
                    (recur uhap)))
                (let [_ (u_freeentries ed buf uhp uhpp)]
                  nil)))))))))

(defn u_blockfree [^Editor ed ^S_file_buffer buf]
  (loop []
    (if (some? (.b_u_oldhead buf))
      (let [_ (u_freeheader ed buf (.b_u_oldhead buf) nil)]
        (recur))
      nil)))

(defn u_clearall [^Editor ed ^S_file_buffer buf]
  (let [_ (.set_b_u_curhead buf nil)
        _ (.set_b_u_oldhead buf (.b_u_curhead buf))
        _ (.set_b_u_newhead buf (.b_u_oldhead buf))
        _ (.set_b_u_synced buf (boolean true))
        _ (.set_b_u_numhead buf 0)
        _ (.set_ul_line ^T_undoline_T (.-b_u_line_ptr buf) nil)
        _ (.set_ul_len ^T_undoline_T (.-b_u_line_ptr buf) 0)
        _ (.set_ul_textlen ^T_undoline_T (.-b_u_line_ptr buf) 0)
        _ (.set_b_u_line_lnum buf 0)]
    nil))

(defn u_clearallandblockfree [^Editor ed ^S_file_buffer buf]
  (let [_ (u_blockfree ed buf)
        _ (u_clearall ed buf)]
    nil))

(defn buf_freeall [^Editor ed ^S_file_buffer buf ^long flags]
  (let [^T_bufref_T bufref (new-T_bufref_T)]
    (let [is_curbuf (identical? buf (g ed curbuf))
          _ (.set_b_locked buf (i32 (inc (.b_locked buf))))
          _ (.set_b_locked_split buf (i32 (inc (.b_locked_split buf))))
          _ (set_bufref ed bufref buf)
          _ (.set_b_locked buf (i32 (dec (.b_locked buf))))
          _ (.set_b_locked_split buf (i32 (dec (.b_locked_split buf))))]
      (if (and (identical? buf (g ed curbuf)) (not is_curbuf))
        false
        (do (if (and (identical? buf (g ed curbuf)) (not (zero? (g ed VIsual_active))))
              (let [_ (end_visual_mode ed)]
                nil)
              nil)
          (let [_ (ml_close ed buf true)
                _ (.set_ml_line_count ^S_memline (.-b_ml buf) 0)]
            (if (== (bit-and flags (e BFA_KEEP_UNDO)) 0)
              (let [_ (u_clearallandblockfree ed buf)]
                (let [_ (.set_b_flags buf (bit-and (.b_flags buf) -65))]
                  true))
              (let [_ (.set_b_flags buf (bit-and (.b_flags buf) -65))]
                true))))))))

(defn free_wininfo [^Editor ed ^S_wininfo_S wip]
  (if (.wi_optset wip)
    (let [_ (clear_winopt ed (.-wi_opt wip))]
      nil)
    nil))

(defn clear_wininfo [^Editor ed ^S_file_buffer buf]
  (loop []
    (if (some? (.b_wininfo buf))
      (let [^S_wininfo_S wip (.b_wininfo buf)
            _ (.set_b_wininfo buf (.wi_next wip))
            _ (free_wininfo ed wip)]
        (recur))
      nil)))

(defn free_buf_options [^Editor ed ^S_file_buffer buf free_p_ff]
  (let [_ (clear_string_option ed (Ptr. ^objects (.-b_p_mps buf) 0))
        _ (clear_string_option ed (Ptr. ^objects (.-b_p_isk buf) 0))
        _ (clear_string_option ed (Ptr. ^objects (.-b_p_nf buf) 0))
        _ (clear_string_option ed (Ptr. ^objects (.-b_p_qe buf) 0))
        _ (aset ^longs (.-b_p_ul buf) 0 -123456)]
    nil))

(defn is_map_locked [^Editor ed]
  (if (> (g ed map_locked) 0)
    (let [_ (long (emsg ed (gettext_ ed (BytePtr. (g ed e_cannot_change_mappings_while_listing) 0))))]
      true)
    false))

(defn validate_maphash [^Editor ed]
  (if (zero? (g ed maphash_valid))
    (let [_ (Rt/zero (Ptr. (g ed maphash) 0) 256)
          _ (g! ed maphash_valid (e TRUE))]
      nil)
    nil))

(defn map_free [^Editor ed ^Ptr mpp]
  (let [^S_mapblock mp (.get mpp)]
    (if (some? (.m_alt mp))
      (let [_ (.set_m_alt ^S_mapblock (.m_alt mp) nil)]
        (let [_ (.put mpp (aget ^objects (.-m_next mp) 0))]
          nil))
      (let [_ (.put mpp (aget ^objects (.-m_next mp) 0))]
        nil))))

(defn map_clear_mode [^Editor ed ^S_file_buffer buf mode local abbr]
  (let [mode (long mode)]
    (loop [st 0
           ^S_file_buffer buf buf
           mode mode
           local local
           abbr abbr
           ^S_mapblock mp nil
           ^Ptr mpp nil
           hash_ 0]
      (case st
        0
        (if (is_map_locked ed)
          nil
          (let [_ (validate_maphash ed)
                hash_ 0]
            (recur 1 buf mode local abbr mp mpp hash_)))
        1
        (if (< hash_ 256)
          (if abbr
            (if (> hash_ 0)
              nil
              (if local
                (let [^Ptr mpp (Ptr. ^objects (.-b_first_abbr buf) 0)]
                  (recur 2 buf mode local abbr mp mpp hash_))
                (let [^Ptr mpp (Ptr. (g ed first_abbr) 0)]
                  (recur 2 buf mode local abbr mp mpp hash_))))
            (if local
              (let [^Ptr mpp (Ptr. ^objects (.-b_maphash buf) hash_)]
                (recur 2 buf mode local abbr mp mpp hash_))
              (let [^Ptr mpp (Ptr. (g ed maphash) hash_)]
                (recur 2 buf mode local abbr mp mpp hash_))))
          nil)
        2
        (recur 3 buf mode local abbr mp mpp hash_)
        3
        (if (some? (.get mpp))
          (let [^S_mapblock mp (.get mpp)]
            (if (zero? (bit-and (.m_mode mp) mode))
              (recur 4 buf mode local abbr mp mpp hash_)
              (let [_ (.set_m_mode mp (bit-and (.m_mode mp) (bit-not mode)))]
                (if (== (.m_mode mp) 0)
                  (let [_ (map_free ed mpp)]
                    (recur 3 buf mode local abbr mp mpp hash_))
                  (let [new_hash (if (zero? (bit-and (.m_mode mp) 199)) (bit-xor (bit-and (.at ^BytePtr (.m_keys mp) 0) 0xff) 128) (bit-and (.at ^BytePtr (.m_keys mp) 0) 0xff))]
                    (if (and (not abbr) (not (== new_hash hash_)))
                      (let [_ (.put mpp (aget ^objects (.-m_next mp) 0))]
                        (do (if local
                              (let [_ (aset ^objects (.-m_next mp) 0 (aget ^objects (.-b_maphash buf) new_hash))
                                    _ (aset ^objects (.-b_maphash buf) new_hash mp)]
                                nil)
                              (let [_ (aset ^objects (.-m_next mp) 0 (aget (g ed maphash) new_hash))
                                    _ (aset (g ed maphash) new_hash mp)]
                                nil))
                          (recur 3 buf mode local abbr mp mpp hash_)))
                      (recur 4 buf mode local abbr mp mpp hash_)))))))
          (let [hash_ (i32 (inc hash_))]
            (recur 1 buf mode local abbr mp mpp hash_)))
        4
        (let [^Ptr mpp (Ptr. ^objects (.-m_next mp) 0)]
          (recur 3 buf mode local abbr mp mpp hash_))
        (throw (IllegalStateException. "no state"))))))

(defn free_buffer_stuff [^Editor ed ^S_file_buffer buf free_options]
  (if free_options
    (let [_ (clear_wininfo ed buf)
          _ (free_buf_options ed buf true)]
      (let [_ (map_clear_mode ed buf (e MAP_ALL_MODES) true false)
            _ (map_clear_mode ed buf (e MAP_ALL_MODES) true true)]
        nil))
    (let [_ (map_clear_mode ed buf (e MAP_ALL_MODES) true false)
          _ (map_clear_mode ed buf (e MAP_ALL_MODES) true true)]
      nil)))

(defn check_status [^Editor ed ^S_file_buffer buf]
  (let [^S_window_S wp (g ed curwin)]
    (if (and (identical? (.w_buffer wp) buf) (not (zero? (.w_status_height wp))))
      (let [_ (.set_w_redr_status wp (boolean true))
            _ (set_must_redraw ed (e UPD_VALID))]
        nil)
      nil)))

(defn unchanged [^Editor ed ^S_file_buffer buf ff always_inc_changedtick]
  (if (zero? (long (aget ^ints (.-b_changed buf) 0)))
    (if always_inc_changedtick
      (let [_ (.set_b_changedtick buf (inc (.b_changedtick buf)))]
        nil)
      nil)
    (let [_ (aset ^ints (.-b_changed buf) 0 (unchecked-int 0))
          _ (check_status ed buf)
          _ (g! ed redraw_tabline (e TRUE))
          _ (.set_b_changedtick buf (inc (.b_changedtick buf)))]
      nil)))

(defn buf_clear_file [^Editor ed ^S_file_buffer buf]
  (let [_ (.set_ml_line_count ^S_memline (.-b_ml buf) 1)
        _ (unchanged ed buf true true)
        _ (.set_b_shortname buf (boolean false))
        _ (.set_ml_root ^S_memline (.-b_ml buf) nil)
        _ (.set_ml_flags ^S_memline (.-b_ml buf) (e ML_EMPTY))]
    nil))

(defn close_buffer [^Editor ed ^S_window_S win ^S_file_buffer buf action abort_if_last ignore_abort set_context]
  (let [action (long action)
        ^T_bufref_T bufref (new-T_bufref_T)]
    (loop [st 0
           ^S_window_S win win
           ^S_file_buffer buf buf
           action action
           abort_if_last abort_if_last
           ignore_abort ignore_abort
           set_context set_context
           unload_buf false
           wipe_buf false
           win_valid false
           closed_popup false]
      (case st
        0
        (let [unload_buf (not (== action 0))
              wipe_buf (or (== action (e DOBUF_WIPE)) (== action (e DOBUF_WIPE_REUSE)))
              del_buf (or (== action (e DOBUF_DEL)) wipe_buf)
              win_valid (win_valid_any_tab ed win)
              closed_popup (and (and (some? win) (not win_valid)) false)]
          (if (and (or del_buf wipe_buf) (not (can_unload_buffer ed buf)))
            false
            (do (if (and (and set_context win_valid) (identical? (.w_buffer win) buf))
                  (do (if (== (.b_nwindows buf) 1)
                        (let [_ (set_last_cursor ed win)]
                          nil)
                        nil)
                    (let [_ (buflist_setfpos ed buf win (if (== (aget ^longs (.-lnum ^T_pos_T (.-w_cursor win)) 0) 1) 0 (aget ^longs (.-lnum ^T_pos_T (.-w_cursor win)) 0)) (long (aget ^ints (.-col ^T_pos_T (.-w_cursor win)) 0)) true)]
                      nil))
                  nil)
              (let [_ (set_bufref ed bufref buf)]
                (if (and (and (or win_valid closed_popup) (identical? (.w_buffer win) buf)) (== (.b_nwindows buf) 1))
                  (if abort_if_last
                    (let [_ (long (emsg ed (gettext_ ed (BytePtr. (g ed e_autocommands_caused_command_to_abort) 0))))]
                      false)
                    (let [win_valid (and win_valid (win_valid_any_tab ed win))]
                      (recur 1 win buf action abort_if_last ignore_abort set_context unload_buf wipe_buf win_valid closed_popup)))
                  (recur 1 win buf action abort_if_last ignore_abort set_context unload_buf wipe_buf win_valid closed_popup))))))
        1
        (let [hiding_buf (or (<= (.b_nwindows buf) 0) (and (and (or win_valid closed_popup) (identical? (.w_buffer win) buf)) (== (.b_nwindows buf) 1)))]
          (if (or (not hiding_buf) (not unload_buf))
            false
            (let [del_buf true]
              (if (buf_freeall ed buf (i32 (+ (i32 (+ (if del_buf (e BFA_DEL) 0) (if wipe_buf (e BFA_WIPE) 0))) (if ignore_abort (e BFA_IGNORE_ABORT) 0))))
                (let [win_valid (and win_valid (win_valid_any_tab ed win))]
                  (do (if (and (or win_valid closed_popup) (identical? (.w_buffer win) buf))
                        (let [_ (.set_b_nwindows buf (i32 (dec (.b_nwindows buf))))
                              _ (.set_w_buffer win nil)]
                          nil)
                        nil)
                    (if del_buf
                      (let [_ (free_buffer_stuff ed buf true)
                            _ (.set_b_flags buf 6)
                            _ (.set_b_p_initialized buf (boolean false))]
                        (let [_ (buf_clear_file ed buf)]
                          true))
                      (let [_ (buf_clear_file ed buf)]
                        true))))
                false))))
        (throw (IllegalStateException. "no state"))))))

(defn changed_internal [^Editor ed]
  (let [_ (aset ^ints (.-b_changed (g ed curbuf)) 0 (unchecked-int (e TRUE)))
        _ (check_status ed (g ed curbuf))
        _ (g! ed redraw_tabline (e TRUE))]
    nil))

(defn changed [^Editor ed]
  (if (zero? (long (aget ^ints (.-b_changed (g ed curbuf)) 0)))
    (let [_ (changed_internal ed)]
      (let [_ (.set_b_changedtick (g ed curbuf) (inc (.b_changedtick (g ed curbuf))))
            _ (g! ed highlight_match (e FALSE))]
        nil))
    (let [_ (.set_b_changedtick (g ed curbuf) (inc (.b_changedtick (g ed curbuf))))
          _ (g! ed highlight_match (e FALSE))]
      nil)))

(defn open_buffer [^Editor ed]
  (let [^T_bufref_T old_curbuf (new-T_bufref_T)]
    (let [retval true]
      (do (if (ml_open ed (g ed curbuf))
            nil
            (let [_ (close_buffer ed (g ed curwin) (g ed curbuf) 0 false false false)
                  _ (long (emsg ed (gettext_ ed (BytePtr. (g ed e_cannot_allocate_any_buffer_exiting) 0))))
                  _ (g! ed v_dying 2)
                  _ (getout ed 2)]
              nil))
