                (recur 9 p i delim delim_len)))
            (recur 9 p i delim delim_len))))
      1
      (if (zero? (bit-and (.get p) 0xff))
        (recur 2 p i delim delim_len)
        (if (and (and (== (bit-and (.at p 0) 0xff) 41) (== (long (musl_strncmp ed (.add p 1) delim delim_len)) 0)) (== (bit-and (.at p (+ delim_len 1)) 0xff) 34))
          (let [^BytePtr p (.add p (+ delim_len 1))]
            (recur 2 p i delim delim_len))
          (let [^BytePtr p (.add p 1)]
            (recur 1 p i delim delim_len))))
      2
      (if (== (bit-and (.at p 0) 0xff) 34)
        (recur 8 p i delim delim_len)
        (recur 9 p i delim delim_len))
      3
      (if (zero? (bit-and (.at p 0) 0xff))
        (recur 4 p i delim delim_len)
        (if (and (== (bit-and (.at p 0) 0xff) 92) (not (== (bit-and (.at p 1) 0xff) (e NUL))))
          (let [^BytePtr p (.add p 1)]
            (recur 5 p i delim delim_len))
          (if (== (bit-and (.at p 0) 0xff) 34)
            (recur 4 p i delim delim_len)
