(defn ml_append_flush [^Editor ed ^S_file_buffer buf lnum ^BytePtr line len flags]
  (let [lnum (long lnum)
        len (long len)
        flags (long flags)]
    (if (> lnum (.ml_line_count ^S_memline (.-b_ml buf)))
      false
      (if (== (.ml_line_lnum ^S_memline (.-b_ml buf)) 0)
        (ml_append_int ed buf lnum line len flags)
        (let [_ (ml_flush_line ed buf)]
          (ml_append_int ed buf lnum line len flags))))))

(defn ml_append_flags [^Editor ed lnum ^BytePtr line len flags]
  (let [lnum (long lnum)
        len (long len)
        flags (long flags)]
    (if (and (nil? (.ml_root ^S_memline (.-b_ml (g ed curbuf)))) (not (open_buffer ed)))
      false
      (ml_append_flush ed (g ed curbuf) lnum line len flags))))

(defn ml_append [^Editor ed ^long lnum ^BytePtr line ^long len]
  (ml_append_flags ed lnum line len 0))

