(defn replace_join [^Editor ed ^long off]
  (loop [st 0
         off off
         i 0
         t1 false]
    (case st
      0
      (let [i (i32 (g ed replace_stack_nr))]
        (recur 1 off i t1))
      1
      (let [i (i32 (dec i))]
        (if (>= i 0)
          (let [t1 (== (bit-and (.at (g ed replace_stack) i) 0xff) (e NUL))]
            (if t1
              (let [t2 off
                    off (i32 (dec off))
                    t1 (<= t2 0)]
                (recur 2 off i t1))
              (recur 2 off i t1)))
          nil))
      2
      (if t1
        (let [_ (g! ed replace_stack_nr (dec (g ed replace_stack_nr)))
              _ (Rt/memmove (.add (g ed replace_stack) i) (.add (.add (g ed replace_stack) i) 1) (- (g ed replace_stack_nr) i))]
          nil)
        (recur 1 off i t1))
      (throw (IllegalStateException. "no state")))))

(defn truncate_spaces [^Editor ed ^BytePtr line ^long len]
  (let [i (i32 (- (i32 len) 1))]
    (loop [i i]
      (if (and (>= i 0) (or (== (bit-and (.at line i) 0xff) 32) (== (bit-and (.at line i) 0xff) 9)))
        (do (if (zero? (bit-and (g ed State) (e REPLACE_FLAG)))
              nil
              (let [_ (replace_join ed 0)]
                nil))
          (let [i (i32 (dec i))]
            (recur i)))
        (let [_ (.set line (i32 (+ i 1)) (unchecked-byte (e NUL)))]
          nil)))))

(defn changed_lines_buf [^Editor ed ^S_file_buffer buf lnum lnume xtra]
  (let [lnum (long lnum)
        lnume (long lnume)
        xtra (long xtra)]
    (if (.b_mod_set buf)
      (do (if (< lnum (.b_mod_top buf))
            (let [_ (.set_b_mod_top buf lnum)]
              nil)
            nil)
        (do (if (< lnum (.b_mod_bot buf))
              (let [_ (.set_b_mod_bot buf (+ (.b_mod_bot buf) xtra))]
                (if (< (.b_mod_bot buf) lnum)
                  (let [_ (.set_b_mod_bot buf lnum)]
                    nil)
                  nil))
              nil)
          (do (if (> (+ lnume xtra) (.b_mod_bot buf))
                (let [_ (.set_b_mod_bot buf (+ lnume xtra))]
                  nil)
                nil)
            (let [_ (.set_b_mod_xlines buf (+ (.b_mod_xlines buf) xtra))]
              nil))))
      (let [_ (.set_b_mod_set buf (boolean true))
            _ (.set_b_mod_top buf lnum)
            _ (.set_b_mod_bot buf (+ lnume xtra))
            _ (.set_b_mod_xlines buf xtra)]
        nil))))

