(defn do_cmdline [^Editor ed ^BytePtr cmdline ^clojure.lang.IFn fgetline ^long flags]
  (let [^objects cmdline_copy (object-array 1)]
    (loop [st 0
           ^BytePtr cmdline cmdline
           ^clojure.lang.IFn fgetline fgetline
           flags flags
           ^BytePtr next_cmdline nil
           used_getline false
           msg_didout_before_start 0
           count_ 0
           did_inc_RedrawingDisabled false
           retval false
           t1 false]
      (case st
        0
        (let [_ (aset cmdline_copy 0 nil)
              used_getline false
              msg_didout_before_start 0
              count_ 0
              did_inc_RedrawingDisabled false
              retval true]
          (if (>= (g ed do_cmdline_call_depth) 200)
            (let [_ (long (emsg ed (gettext_ ed (BytePtr. (g ed e_command_too_recursive) 0))))]
              false)
            (let [_ (g! ed do_cmdline_call_depth (i32 (inc (g ed do_cmdline_call_depth))))
                  _ (g! ed did_emsg (e FALSE))]
              (do (if (and (zero? (bit-and flags (e DOCMD_KEYTYPED))) (zero? (bit-and flags (e DOCMD_GETEXLINE))))
                    (let [_ (g! ed KeyTyped (e FALSE))]
                      nil)
                    nil)
                (let [^BytePtr next_cmdline cmdline]
                  (recur 1 cmdline fgetline flags next_cmdline used_getline msg_didout_before_start count_ did_inc_RedrawingDisabled retval t1))))))
        1
        (do (if (nil? next_cmdline)
              (let [_ (g! ed did_emsg (e FALSE))]
                nil)
              nil)
          (if (nil? next_cmdline)
            (do (if (and (== count_ 1) (not (zero? (bit-and flags (e DOCMD_GETEXLINE)))))
                  (let [_ (g! ed msg_didout (e TRUE))]
                    nil)
                  nil)
              (let [t1 (nil? fgetline)]
                (if t1
                  (recur 2 cmdline fgetline flags next_cmdline used_getline msg_didout_before_start count_ did_inc_RedrawingDisabled retval t1)
