(defn init_highlight [^Editor ed both reset]
  (loop [st 0
         both both
         reset reset
         i 0
         ^Ptr pp nil]
    (case st
      0
      (if both
        (let [_ (g! ed init_highlight_had_both true)
              ^Ptr pp (Ptr. (g ed highlight_init_both) 0)
              i 0]
          (recur 1 both reset i pp))
        (if (g ed init_highlight_had_both)
          (recur 2 both reset i pp)
          nil))
      1
      (if (some? (.at pp i))
        (let [_ (do_highlight ed (.at pp i) reset true)]
          (let [i (i32 (inc i))]
            (recur 1 both reset i pp)))
        (recur 2 both reset i pp))
      2
      (let [^Ptr pp (if (== (bit-and (.get ^BytePtr (aget (g ed p_bg) 0)) 0xff) 108)
                     (let [^Ptr pp (Ptr. (g ed highlight_init_light) 0)]
                       pp)
                     (let [^Ptr pp (Ptr. (g ed highlight_init_dark) 0)]
                       pp))]
        (let [i 0]
          (recur 3 both reset i pp)))
      3
      (if (some? (.at pp i))
        (let [_ (do_highlight ed (.at pp i) reset true)]
          (let [i (i32 (inc i))]
            (recur 3 both reset i pp)))
        (do (if (< (g ed t_colors) 8)
              (let [_ (do_highlight ed (BytePtr/lit "Visual term=reverse cterm=reverse ctermbg=NONE ctermfg=NONE") false true)]
                nil)
              nil)
          (if (<= (g ed t_colors) 8)
            (if (== (bit-and (.get ^BytePtr (aget (g ed p_bg) 0)) 0xff) 108)
              (let [_ (do_highlight ed (BytePtr/lit "Search ctermfg=black") false true)]
                (let [_ (resolve_fallback_fg_to_rgb ed)
                      _ (resolve_fallback_bg_to_rgb ed)]
                  nil))
              (let [_ (resolve_fallback_fg_to_rgb ed)
                    _ (resolve_fallback_bg_to_rgb ed)]
                nil))
            (let [_ (resolve_fallback_fg_to_rgb ed)
                  _ (resolve_fallback_bg_to_rgb ed)]
              nil))))
      (throw (IllegalStateException. "no state")))))

(defn may_adjust_color_count [^Editor ed ^long val_]
  (if (== val_ (g ed t_colors))
