    (let [^BytePtr newp (if (== col 0)
                         (let [^BytePtr newp (vim_strsave ed (BytePtr/lit ""))]
                           newp)
                         (let [^BytePtr newp (vim_strnsave ed old_line col)]
                           newp))]
      (let [deleted (i32 (- (long (ml_get_len ed lnum)) col))]
        (if (nil? newp)
          false
          (let [_ (ml_replace ed lnum newp false)
                _ (inserted_bytes ed lnum (long (aget ^ints (.-col ^T_pos_T (.-w_cursor (g ed curwin))) 0)) (i32 (- deleted)))]
            (if (and fixpos (> (long (aget ^ints (.-col ^T_pos_T (.-w_cursor (g ed curwin))) 0)) 0))
              (let [_ (aset ^ints (.-col ^T_pos_T (.-w_cursor (g ed curwin))) 0 (unchecked-int (i32 (dec (long (aget ^ints (.-col ^T_pos_T (.-w_cursor (g ed curwin))) 0))))))]
