                                                _ (.set_ip_high ^S_info_pointer (.at ^Ptr (.ml_stack ^S_memline (.-b_ml buf)) (.ml_stack_top ^S_memline (.-b_ml buf))) (+ (.ip_high ^S_info_pointer (.at ^Ptr (.ml_stack ^S_memline (.-b_ml buf)) (.ml_stack_top ^S_memline (.-b_ml buf)))) (.ml_locked_lineadd ^S_memline (.-b_ml buf))))]
                                            nil))
                                      (let [_ (.set_ml_stack_top ^S_memline (.-b_ml buf) (i32 (inc (.ml_stack_top ^S_memline (.-b_ml buf)))))]
                                        (let [ret true]
                                          ret)))))))
                            (let [_ (iemsg ed (BytePtr. (g ed e_pointer_block_id_wrong_four) 0))]
                              ret)))
                        (let [ret true]
                          ret))))
                  (do (if (< idx (i32 (- count_ 1)))
                        (let [_ (Rt/moveStructs (Ptr. ^objects (.-db_line dp) idx) (Ptr. ^objects (.-db_line dp) (i32 (+ idx 1))) (i32 (- (i32 (- count_ idx)) 1)))]
                          nil)
