(defn cursor_correct [^Editor ed]
  (loop [st 0
         above 0
         topline 0
         below 0
         botline 0
         above_wanted 0
         below_wanted 0
         cln 0]
    (case st
      0
      (let [above 0
            below 0
            so (long (get_scrolloff_value ed))
            above_wanted (i32 so)
            below_wanted (i32 so)]
        (if (> (g ed mouse_dragging) 0)
          (let [above_wanted (i32 (- (g ed mouse_dragging) 1))
                below_wanted (i32 (- (g ed mouse_dragging) 1))]
            (recur 1 above topline below botline above_wanted below_wanted cln))
          (recur 1 above topline below botline above_wanted below_wanted cln)))
      1
      (if (== (.w_topline (g ed curwin)) 1)
        (let [above_wanted 0
              max_off (i32 (quot (.w_height (g ed curwin)) 2))]
          (if (> below_wanted max_off)
            (let [below_wanted max_off]
              (recur 2 above topline below botline above_wanted below_wanted cln))
            (recur 2 above topline below botline above_wanted below_wanted cln)))
        (recur 2 above topline below botline above_wanted below_wanted cln))
      2
      (let [_ (validate_botline ed)]
        (if (and (== (.w_botline (g ed curwin)) (+ (.ml_line_count ^S_memline (.-b_ml (g ed curbuf))) 1)) (== (g ed mouse_dragging) 0))
          (let [below_wanted 0
                max_off (i32 (quot (i32 (- (.w_height (g ed curwin)) 1)) 2))]
            (if (> above_wanted max_off)
              (let [above_wanted max_off]
                (recur 3 above topline below botline above_wanted below_wanted cln))
              (recur 3 above topline below botline above_wanted below_wanted cln)))
          (recur 3 above topline below botline above_wanted below_wanted cln)))
      3
      (let [cln (aget ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0)]
        (if (and (>= cln (+ (.w_topline (g ed curwin)) above_wanted)) (< cln (- (.w_botline (g ed curwin)) below_wanted)))
          nil
          (let [topline (.w_topline (g ed curwin))
                botline (- (.w_botline (g ed curwin)) 1)]
            (recur 4 above topline below botline above_wanted below_wanted cln))))
      4
      (if (and (or (< above above_wanted) (< below below_wanted)) (< topline botline))
        (if (and (< below below_wanted) (or (<= below above) (>= above above_wanted)))
          (let [t1 (long (plines ed botline))
                below (i32 (+ below t1))
                botline (dec botline)]
            (recur 5 above topline below botline above_wanted below_wanted cln))
          (recur 5 above topline below botline above_wanted below_wanted cln))
        (if (or (== topline botline) (== botline 0))
          (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 topline)]
            (let [_ (check_cursor_moved ed (g ed curwin))
                  _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
              nil))
          (if (> topline botline)
            (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 botline)]
              (let [_ (check_cursor_moved ed (g ed curwin))
                    _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
                nil))
            (do (if (and (< cln topline) (> (.w_topline (g ed curwin)) 1))
                  (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 topline)
                        _ (.set_w_valid (g ed curwin) (bit-and (.w_valid (g ed curwin)) -28))]
                    nil)
                  nil)
              (if (and (> cln botline) (<= (.w_botline (g ed curwin)) (.ml_line_count ^S_memline (.-b_ml (g ed curbuf)))))
                (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 botline)
                      _ (.set_w_valid (g ed curwin) (bit-and (.w_valid (g ed curwin)) -28))]
                  (let [_ (check_cursor_moved ed (g ed curwin))
                        _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
                    nil))
                (let [_ (check_cursor_moved ed (g ed curwin))
                      _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
                  nil))))))
      5
      (if (and (< above above_wanted) (or (< above below) (>= below below_wanted)))
        (let [t2 (long (plines ed topline))
              above (i32 (+ above t2))
              topline (inc topline)]
          (recur 6 above topline below botline above_wanted below_wanted cln))
        (recur 6 above topline below botline above_wanted below_wanted cln))
      6
      (recur 4 above topline below botline above_wanted below_wanted cln)
      (throw (IllegalStateException. "no state")))))

(defn scroll_redraw [^Editor ed ^long up ^long count_]
  (loop [st 0
         up up
         count_ count_
         prev_topline 0
         prev_skipcol 0
         prev_lnum 0]
    (case st
      0
      (let [prev_topline (.w_topline (g ed curwin))
            prev_skipcol (.w_skipcol (g ed curwin))
            prev_lnum (aget ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0)]
        (do (if (zero? up)
              (let [_ (scrolldown ed count_ true)]
                nil)
              (let [_ (scrollup ed count_ true)]
                nil))
          (if (> (long (get_scrolloff_value ed)) 0)
            (let [_ (cursor_correct ed)
                  _ (check_cursor_moved ed (g ed curwin))
                  _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
              (recur 1 up count_ prev_topline prev_skipcol prev_lnum))
            (recur 3 up count_ prev_topline prev_skipcol prev_lnum))))
      1
      (if (and (== (.w_topline (g ed curwin)) prev_topline) (== (.w_skipcol (g ed curwin)) prev_skipcol))
        (if (zero? up)
          (if (or (or (< (aget ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0) prev_lnum) (== prev_topline 1)) (not (cursor_up ed 1 false)))
            (recur 3 up count_ prev_topline prev_skipcol prev_lnum)
            (recur 2 up count_ prev_topline prev_skipcol prev_lnum))
          (if (or (> (aget ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0) prev_lnum) (not (cursor_down ed 1 false)))
            (recur 3 up count_ prev_topline prev_skipcol prev_lnum)
            (recur 2 up count_ prev_topline prev_skipcol prev_lnum)))
        (recur 3 up count_ prev_topline prev_skipcol prev_lnum))
      2
      (let [_ (check_cursor_moved ed (g ed curwin))
            _ (.set_w_valid (g ed curwin) (bit-or (.w_valid (g ed curwin)) (e VALID_TOPLINE)))]
        (recur 1 up count_ prev_topline prev_skipcol prev_lnum))
      3
      (let [_ (cursor_correct_sms ed)]
        (if (== (aget ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0) prev_lnum)
          (let [_ (redraw_later ed (e UPD_VALID))]
            nil)
          (let [_ (coladvance ed (.w_curswant (g ed curwin)))]
            (let [_ (redraw_later ed (e UPD_VALID))]
              nil))))
      (throw (IllegalStateException. "no state")))))

(defn scroll_with_sms [^Editor ed ^long dir ^long count_ ^LongPtr curscount]
  (let [prev_sms (long (aget ^ints (.-wo_sms ^T_winopt_T (.-w_onebuf_opt (g ed curwin))) 0))
        prev_skipcol (.w_skipcol (g ed curwin))
        prev_topline (.w_topline (g ed curwin))
        _ (aset ^ints (.-wo_sms ^T_winopt_T (.-w_onebuf_opt (g ed curwin))) 0 (unchecked-int (e TRUE)))
