    (if (and (zero? prev_sms) (> (.w_skipcol (g ed curwin)) 0))
      (let [fixdir dir]
        (let [fixdir (if (> (long (musl_labs ed (- (.w_topline (g ed curwin)) prev_topline))) (if (== dir -1) 1 0))
                      (let [fixdir (i32 (* dir -1))]
