                (let [_ (aset ^ints (.-wo_sms ^T_winopt_T (.-w_onebuf_opt (g ed curwin))) 0 (unchecked-int prev_sms))]
                  (or (not (== (.w_topline (g ed curwin)) prev_topline)) (not (== (.w_skipcol (g ed curwin)) prev_skipcol)))))))))
      (let [_ (aset ^ints (.-wo_sms ^T_winopt_T (.-w_onebuf_opt (g ed curwin))) 0 (unchecked-int prev_sms))]
        (or (not (== (.w_topline (g ed curwin)) prev_topline)) (not (== (.w_skipcol (g ed curwin)) prev_skipcol)))))))

