      (if (or (and (== dir -1) (== (.w_topline (g ed curwin)) 1)) (and (== dir (e FORWARD)) (> (.w_botline (g ed curwin)) (.ml_line_count ^S_memline (.-b_ml (g ed curbuf))))))
