                      _ (mark_adjust_nofold ed line1 line2 (- last_line line2) 0)]
                  (do (if (>= dest line2)
                        (let [_ (mark_adjust_nofold ed (+ line2 1) dest (- num_lines) 0)]
                          (if (== (bit-and (.cmod_flags (g ed cmdmod)) (e CMOD_LOCKMARKS)) 0)
                            (let [_ (aset ^longs (.-lnum ^T_pos_T (.-b_op_start (g ed curbuf))) 0 (+ (- dest num_lines) 1))
                                  _ (aset ^longs (.-lnum ^T_pos_T (.-b_op_end (g ed curbuf))) 0 dest)]
                              nil)
                            nil))
                        (let [_ (mark_adjust_nofold ed (+ dest 1) (- line1 1) num_lines 0)]
                          (if (== (bit-and (.cmod_flags (g ed cmdmod)) (e CMOD_LOCKMARKS)) 0)
                            (let [_ (aset ^longs (.-lnum ^T_pos_T (.-b_op_start (g ed curbuf))) 0 (+ dest 1))
                                  _ (aset ^longs (.-lnum ^T_pos_T (.-b_op_end (g ed curbuf))) 0 (+ dest num_lines))]
                              nil)
                            nil)))
                    (do (if (== (bit-and (.cmod_flags (g ed cmdmod)) (e CMOD_LOCKMARKS)) 0)
