                            nil)
                          nil)
                      (let [_ (mark_adjust_nofold ed (+ (- last_line num_lines) 1) last_line (- (- (- last_line dest) extra)) 0)]
                        (if (u_save ed (- (+ line1 extra) 1) (+ (+ line2 extra) 1))
