                                (let [_ (ml_delete_flags ed (+ line1 extra) (e ML_DEL_MESSAGE))]
                                  (let [l (inc l)]
                                    (recur l)))
                                (do (if (and (zero? (g ed global_busy)) (> num_lines (aget (g ed p_report) 0)))
                                      (let [_ (long (whim.cljhost/vim_snprintf ed (g ed IObuff) (long (iobuff_room ed)) (NGETTEXT ed (BytePtr/lit "%ld line moved") (BytePtr/lit "%ld lines moved") num_lines) (object-array [(Long/valueOf num_lines)])))
                                            _ (long (msg ed (iobuff_or ed (NGETTEXT ed (BytePtr/lit "%ld line moved") (BytePtr/lit "%ld lines moved") num_lines))))]
                                        nil)
