                                        (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 dest)]
                                          nil)
                                        (let [_ (aset ^longs (.-lnum ^T_pos_T (.-w_cursor (g ed curwin))) 0 (+ (+ dest (- line2 line1)) 1))]
                                          nil))
                                    (if (< line1 dest)
