                _ (.set_start_char_vcols bdp incr)]
            (if (< (.start_vcol bdp) (long (aget ^ints (.-start_vcol oap) 0)))
              (let [_ (.set_end_vcol bdp (.start_vcol bdp))
                    _ (.set_is_short bdp (boolean true))]
                (if (or (zero? is_del) (== (.op_type oap) (e OP_APPEND)))
                  (let [_ (.set_endspaces bdp (i32 (+ (i32 (- (long (aget ^ints (.-end_vcol oap) 0)) (long (aget ^ints (.-start_vcol oap) 0)))) 1)))]
