                        _ (.set_textstart bdp pstart)]
                    nil)))
              (let [_ (.set_startspaces bdp (i32 (- (.start_vcol bdp) (long (aget ^ints (.-start_vcol oap) 0)))))]
                (do (if (and (not (zero? is_del)) (not (zero? (.startspaces bdp))))
                      (let [_ (.set_startspaces bdp (i32 (- (.start_char_vcols bdp) (.startspaces bdp))))]
