                          (let [_ (.set_endspaces bdp (i32 (- (.start_char_vcols bdp) (.startspaces bdp))))]
                            (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))
                          (if (== (.op_type oap) (e OP_APPEND))
                            (let [_ (.set_startspaces bdp (i32 (+ (.startspaces bdp) (i32 (+ (i32 (- (long (aget ^ints (.-end_vcol oap) 0)) (long (aget ^ints (.-start_vcol oap) 0)))) 1)))))
                                  _ (.set_endspaces bdp (i32 (- (.start_char_vcols bdp) (.startspaces bdp))))]
                              (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))
                            (let [_ (.set_startspaces bdp (i32 (+ (i32 (- (long (aget ^ints (.-end_vcol oap) 0)) (long (aget ^ints (.-start_vcol oap) 0)))) 1)))]
                              (if (and (not (zero? is_del)) (not (== (.op_type oap) (e OP_LSHIFT))))
                                (let [_ (.set_startspaces bdp (i32 (- (.start_char_vcols bdp) (i32 (- (.start_vcol bdp) (long (aget ^ints (.-start_vcol oap) 0)))))))
                                      _ (.set_endspaces bdp (i32 (- (i32 (- (.end_vcol bdp) (long (aget ^ints (.-end_vcol oap) 0)))) 1)))]
                                  (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))
                                (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))))))
                      (let [_ (init_chartabsize_arg ed cts (g ed curwin) lnum (.end_vcol bdp) line pend)
                            ^BytePtr prev_pend pend]
                        (recur 2 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend)))))))))
        2
        (if (and (<= (.cts_vcol cts) (long (aget ^ints (.-end_vcol oap) 0))) (not (== (bit-and (.get ^BytePtr (.cts_ptr cts)) 0xff) (e NUL))))
          (let [^BytePtr prev_pend (.cts_ptr cts)
                incr (long (lbr_chartabsize_adv ed cts))
                _ (.set_cts_vcol cts (i32 (+ (.cts_vcol cts) incr)))]
            (recur 2 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))
          (let [_ (.set_end_vcol bdp (.cts_vcol cts))
                ^BytePtr pend (.cts_ptr cts)]
            (if (and (<= (.end_vcol bdp) (long (aget ^ints (.-end_vcol oap) 0))) (or (or (zero? is_del) (== (.op_type oap) (e OP_APPEND))) (== (.op_type oap) (e OP_REPLACE))))
              (let [_ (.set_is_short bdp (boolean true))]
