                  (let [_ (.set_endspaces bdp 0)]
                    (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))))
              (if (> (.end_vcol bdp) (long (aget ^ints (.-end_vcol oap) 0)))
                (let [_ (.set_endspaces bdp (i32 (- (i32 (- (.end_vcol bdp) (long (aget ^ints (.-end_vcol oap) 0)))) 1)))]
