                        (let [^BytePtr pend prev_pend]
                          (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend))))
                    (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend)))
                (recur 3 oap bdp lnum is_del incr pend pstart line prev_pstart prev_pend)))))
        3
