                                 (let [^BytePtr pstart prev_pstart]
                                   pstart)
                                 pstart)]
            (let [_ (.set_textlen bdp (i32 (.sub pend pstart)))]
              (let [_ (.set_textcol bdp (i32 (.sub pstart line)))
                    _ (.set_textstart bdp pstart)]
                nil))))
        (throw (IllegalStateException. "no state"))))))

(defn yank_copy_line [^Editor ed ^S_block_def bd ^long y_idx ^long exclude_trailing_space]
  (do (if (zero? exclude_trailing_space)
        nil
        (let [_ (.set_endspaces bd 0)]
          nil))
    (let [^BytePtr pnew (BytePtr/alloc (i32 (+ (i32 (+ (i32 (+ (.startspaces bd) (.endspaces bd))) (.textlen bd))) 1)))
          _ (aset ^objects (.-string ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx)) 0 pnew)
          _ (Rt/memset pnew (unchecked-int 32) (.startspaces bd))
          ^BytePtr pnew (.add pnew (.startspaces bd))
          _ (Rt/memmove pnew ^BytePtr (.textstart bd) (.textlen bd))
          ^BytePtr pnew (.add pnew (.textlen bd))
          _ (Rt/memset pnew (unchecked-int 32) (.endspaces bd))
          ^BytePtr pnew (.add pnew (.endspaces bd))]
      (if (zero? exclude_trailing_space)
        (let [_ (.put pnew (unchecked-byte (e NUL)))
              _ (.set_length ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx) (.sub pnew ^BytePtr (aget ^objects (.-string ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx)) 0)))]
          true)
        (let [s (i32 (+ (.textlen bd) (.endspaces bd)))]
          (loop [^BytePtr pnew pnew
                 s s]
            (if (and (> s 0) (or (== (bit-and (.get (.add (.add ^BytePtr (.textstart bd) s) (- 1))) 0xff) 32) (== (bit-and (.get (.add (.add ^BytePtr (.textstart bd) s) (- 1))) 0xff) 9)))
              (let [s (i32 (- (i32 (- s (long (utf_head_off ed (.textstart bd) (.add (.add ^BytePtr (.textstart bd) s) (- 1)))))) 1))
                    ^BytePtr pnew (.add pnew -1)]
                (recur pnew s))
              (let [_ (.put pnew (unchecked-byte (e NUL)))
                    _ (.set_length ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx) (.sub pnew ^BytePtr (aget ^objects (.-string ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx)) 0)))]
                true))))))))

(defn charwise_block_prep [^Editor ed ^T_pos_T start ^T_pos_T end ^S_block_def bdp lnum inclusive]
  (let [lnum (long lnum)
        inclusive (long inclusive)
        ^ints cs (int-array 1)
        ^ints ce (int-array 1)]
    (let [startcol 0
          endcol (e MAXCOL)
          plen (long (ml_get_len ed lnum))
          ^BytePtr p (ml_get ed lnum)
          _ (.set_startspaces bdp 0)
          _ (.set_endspaces bdp 0)
          _ (.set_is_oneChar bdp (boolean false))
          _ (.set_start_char_vcols bdp 0)]
      (let [startcol (if (== lnum (aget ^longs (.-lnum start) 0))
                      (let [startcol (long (aget ^ints (.-col start) 0))]
                        (if (zero? (g ed virtual_op))
                          startcol
                          (let [_ (getvcol ed (g ed curwin) start (IntPtr. cs 0) nil (IntPtr. ce 0) 0)]
                            (if (and (not (== (long (aget ce 0)) (long (aget cs 0)))) (> (.coladd start) 0))
                              (let [_ (.set_start_char_vcols bdp (i32 (+ (i32 (- (long (aget ce 0)) (long (aget cs 0)))) 1)))
                                    _ (.set_startspaces bdp (i32 (- (.start_char_vcols bdp) (.coladd start))))]
                                (do (if (< (.startspaces bdp) 0)
                                      (let [_ (.set_startspaces bdp 0)]
                                        nil)
                                      nil)
                                  (let [startcol (i32 (inc startcol))]
                                    startcol)))
                              startcol))))
                      startcol)]
        (let [endcol (if (== lnum (aget ^longs (.-lnum end) 0))
                      (let [endcol (long (aget ^ints (.-col end) 0))]
                        (if (zero? (g ed virtual_op))
                          endcol
                          (let [_ (getvcol ed (g ed curwin) end (IntPtr. cs 0) nil (IntPtr. ce 0) 0)]
                            (if (or (== (bit-and (.at p endcol) 0xff) (e NUL)) (and (< (i32 (+ (long (aget cs 0)) (.coladd end))) (long (aget ce 0))) (== (long (utf_head_off ed p (.add p endcol))) 0)))
                              (if (and (== (aget ^longs (.-lnum start) 0) (aget ^longs (.-lnum end) 0)) (== (long (aget ^ints (.-col start) 0)) (long (aget ^ints (.-col end) 0))))
                                (let [_ (.set_is_oneChar bdp (boolean true))
                                      _ (.set_startspaces bdp (i32 (+ (i32 (- (.coladd end) (.coladd start))) inclusive)))
                                      endcol startcol]
                                  endcol)
                                (let [_ (.set_endspaces bdp (i32 (+ (.coladd end) inclusive)))
                                      endcol (i32 (- endcol inclusive))]
                                  endcol))
                              endcol))))
                      endcol)]
          (let [endcol (if (== endcol (e MAXCOL))
                        (let [endcol (long (ml_get_len ed lnum))]
                          endcol)
                        endcol)]
            (if (or (> startcol endcol) (.is_oneChar bdp))
              (let [_ (.set_textlen bdp 0)]
                (let [_ (.set_textcol bdp startcol)
                      _ (.set_textstart bdp (if (<= startcol plen) (.add p startcol) p))]
                  nil))
              (let [_ (.set_textlen bdp (i32 (+ (i32 (- endcol startcol)) inclusive)))]
                (let [_ (.set_textcol bdp startcol)
                      _ (.set_textstart bdp (if (<= startcol plen) (.add p startcol) p))]
                  nil)))))))))

