                    _ (aset ^objects (.-string ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx)) 0 (vim_strnsave ed (ml_get ed lnum) (.length ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) y_idx))))]
                (recur 7 oap deleting mess y_idx curr lnum yanktype yanklines yankendlnum new_ptr j))
