                      _ (aset ^objects (.-string ^T_string_T (.at ^Ptr (.y_array curr) j)) 0 pnew)
                      _ (.set_length ^T_string_T (.at ^Ptr (.y_array curr) j) (+ (.length ^T_string_T (.at ^Ptr (.y_array curr) j)) (.length ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) 0))))
                      j (inc j)
                      _ (aset ^objects (.-string ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) 0)) 0 nil)
                      _ (.set_length ^T_string_T (.at ^Ptr (.y_array (g ed y_current)) 0) 0)
                      y_idx 1]
                  (recur 4 oap deleting mess y_idx curr lnum yanktype yanklines yankendlnum new_ptr j))
                (let [y_idx 0]
