            (recur 5 oap deleting mess y_idx curr lnum yanktype yanklines yankendlnum new_ptr j))
          (let [_ (.set_y_size curr j)
                _ (g! ed y_current curr)]
            (recur 6 oap deleting mess y_idx curr lnum yanktype yanklines yankendlnum new_ptr j)))
        6
        (do (if mess
              (let [yanklines (if (and (and (== yanktype (e MCHAR)) (zero? (.block_mode oap))) (== yanklines 1))
                               (let [yanklines 0]
                                 yanklines)
                               yanklines)]
