                              _ (long (msg ed (iobuff_or ed (NGETTEXT ed (BytePtr/lit "%ld line yanked%s") (BytePtr/lit "%ld lines yanked%s") yanklines))))]
                          nil)
                        (let [_ (long (whim.cljhost/vim_snprintf ed (g ed IObuff) (long (iobuff_room ed)) (NGETTEXT ed (BytePtr/lit "block of %ld line yanked%s") (BytePtr/lit "block of %ld lines yanked%s") yanklines) (object-array [(Long/valueOf yanklines) (BytePtr. namebuf 0)])))
                              _ (long (msg ed (iobuff_or ed (NGETTEXT ed (BytePtr/lit "block of %ld line yanked%s") (BytePtr/lit "block of %ld lines yanked%s") yanklines))))]
                          nil))))
                  nil))
              nil)
          (if (== (bit-and (.cmod_flags (g ed cmdmod)) (e CMOD_LOCKMARKS)) 0)
            (let [_ (.set ^T_pos_T (.-b_op_start (g ed curbuf)) (.-start oap))
