(defn get_map_mode ^long [^Editor ed ^Ptr cmdp forceit]
  (let [^BytePtr p (.get cmdp)
        ^BytePtr t1 p
        ^BytePtr p (.add p 1)
        modec (bit-and (.get t1) 0xff)]
    (if (== modec 105)
      (let [mode (e MODE_INSERT)]
        (let [_ (.put cmdp p)]
          mode))
      (if (== modec 99)
        (let [mode (e MODE_CMDLINE)]
          (let [_ (.put cmdp p)]
            mode))
        (if (and (== modec 110) (not (== (bit-and (.get p) 0xff) 111)))
          (let [mode (e MODE_NORMAL)]
            (let [_ (.put cmdp p)]
              mode))
          (if (== modec 118)
            (let [mode 66]
              (let [_ (.put cmdp p)]
                mode))
            (if (== modec 120)
              (let [mode (e MODE_VISUAL)]
                (let [_ (.put cmdp p)]
