              (if (== modec 115)
                (let [mode (e MODE_SELECT)]
                  (let [_ (.put cmdp p)]
                    mode))
                (if (== modec 111)
                  (let [mode (e MODE_OP_PENDING)]
                    (let [_ (.put cmdp p)]
                      mode))
                  (let [^BytePtr p (.add p -1)]
                    (if forceit
                      (let [mode 24]
                        (let [_ (.put cmdp p)]
                          mode))
                      (let [mode 71]
                        (let [_ (.put cmdp p)]
                          mode)))))))))))))

