(defn check_map_keycodes [^Editor ed]
  (let [^bytes buf (byte-array 3)]
    (loop [st 0
           ^S_mapblock mp nil
           ^BytePtr p nil
           i 0
           abbr 0
           hash_ 0
           ^S_file_buffer bp nil]
      (case st
        0
        (let [_ (validate_maphash ed)
              _ (estack_push ed (e ETYPE_INTERNAL) (BytePtr/lit "mappings") 0)
              ^S_file_buffer bp (g ed curbuf)]
          (recur 1 mp p i abbr hash_ bp))
        1
        (let [abbr 0]
          (recur 2 mp p i abbr hash_ bp))
        2
        (if (<= abbr 1)
          (let [hash_ 0]
            (recur 3 mp p i abbr hash_ bp))
          (if (nil? bp)
            (let [_ (estack_pop ed)]
              nil)
            (let [^S_file_buffer bp nil]
              (recur 1 mp p i abbr hash_ bp))))
        3
        (if (< hash_ 256)
          (if (zero? abbr)
            (if (some? bp)
              (let [^S_mapblock mp (aget ^objects (.-b_maphash bp) hash_)]
                (recur 4 mp p i abbr hash_ bp))
              (let [^S_mapblock mp (aget (g ed maphash) hash_)]
                (recur 4 mp p i abbr hash_ bp)))
            (if (zero? hash_)
              (if (some? bp)
                (let [^S_mapblock mp (aget ^objects (.-b_first_abbr bp) 0)]
                  (recur 4 mp p i abbr hash_ bp))
                (let [^S_mapblock mp (aget (g ed first_abbr) 0)]
                  (recur 4 mp p i abbr hash_ bp)))
              (recur 8 mp p i abbr hash_ bp)))
          (recur 8 mp p i abbr hash_ bp))
        4
        (recur 5 mp p i abbr hash_ bp)
        5
        (if (some? mp)
          (let [i 0]
            (recur 6 mp p i abbr hash_ bp))
          (let [hash_ (i32 (inc hash_))]
            (recur 3 mp p i abbr hash_ bp)))
        6
        (if (<= i 1)
          (let [^BytePtr p (if (== i 0)
                            (let [^BytePtr p (.m_keys mp)]
                              p)
                            (let [^BytePtr p (.m_str mp)]
                              p))]
            (recur 7 mp p i abbr hash_ bp))
          (let [^S_mapblock mp (aget ^objects (.-m_next mp) 0)]
            (recur 5 mp p i abbr hash_ bp)))
        7
        (if (zero? (bit-and (.get p) 0xff))
          (let [i (i32 (inc i))]
            (recur 6 mp p i abbr hash_ bp))
          (let [^BytePtr p (if (== (bit-and (.get p) 0xff) 128)
                            (let [^BytePtr p (.add p 1)]
                              (do (if (< (bit-and (.get p) 0xff) 128)
                                    (let [_ (aset buf 0 (unchecked-byte (bit-and (.at p 0) 0xff)))
                                          _ (aset buf 1 (unchecked-byte (bit-and (.at p 1) 0xff)))
                                          _ (aset buf 2 (unchecked-byte (e NUL)))
                                          _ (add_termcap_entry ed (BytePtr. buf 0) false)]
                                      nil)
                                    nil)
                                (let [^BytePtr p (.add p 1)]
                                  p)))
                            p)]
            (let [^BytePtr p (.add p 1)]
              (recur 7 mp p i abbr hash_ bp))))
        8
        (let [abbr (i32 (inc abbr))]
          (recur 2 mp p i abbr hash_ bp))
        (throw (IllegalStateException. "no state"))))))

