(defn find_next_quote [^Editor ed ^BytePtr line col quotechar ^BytePtr escape]
  (let [col (long col)
        quotechar (long quotechar)]
    (loop [st 0
           ^BytePtr line line
           col col
           quotechar quotechar
           ^BytePtr escape escape]
      (case st
        0
        (let [c (bit-and (.at line col) 0xff)]
          (if (== c (e NUL))
            -1
            (if (and (some? escape) (some? (vim_strchr ed escape c)))
              (let [col (i32 (inc col))]
                (if (== (bit-and (.at line col) 0xff) (e NUL))
                  -1
                  (recur 1 line col quotechar escape)))
              (if (== c quotechar)
                col
                (recur 1 line col quotechar escape)))))
        1
        (let [t1 (long (utfc_ptr2len ed (.add line col)))
              col (i32 (+ col t1))]
          (recur 0 line col quotechar escape))
        (throw (IllegalStateException. "no state"))))))

(defn find_prev_quote [^Editor ed ^BytePtr line col_start quotechar ^BytePtr escape]
  (let [col_start (long col_start)
        quotechar (long quotechar)]
    (loop [st 0
           ^BytePtr line line
           col_start col_start
           quotechar quotechar
           ^BytePtr escape escape
           n 0]
      (case st
        0
