        1
        (if (> col_start 0)
          (let [col_start (i32 (dec col_start))
                t1 (long (utf_head_off ed line (.add line col_start)))
                col_start (i32 (- col_start t1))
                n 0]
            (if (some? escape)
              (recur 2 line col_start quotechar escape n)
              (recur 3 line col_start quotechar escape n)))
          col_start)
        2
        (if (and (> (i32 (- col_start n)) 0) (some? (vim_strchr ed escape (bit-and (.at line (i32 (- (i32 (- col_start n)) 1))) 0xff))))
          (let [n (i32 (inc n))]
            (recur 2 line col_start quotechar escape n))
          (recur 3 line col_start quotechar escape n))
        3
        (if (zero? (bit-and n 1))
          (if (== (bit-and (.at line col_start) 0xff) quotechar)
            col_start
            (recur 4 line col_start quotechar escape n))
          (let [col_start (i32 (- col_start n))]
            (recur 4 line col_start quotechar escape n)))
        4
        (recur 1 line col_start quotechar escape n)
        (throw (IllegalStateException. "no state"))))))

