(defn match_keyprotocol ^long [^Editor ed ^BytePtr term]
  (let [^objects p (object-array 1)
        ^T_regmatch_T regmatch (new-T_regmatch_T)]
    (loop [st 0
           ^BytePtr term term
           len 0
           ^BytePtr buf nil
           ret 0
           prot 0]
      (case st
        0
        (let [len (i32 (+ (i32 (long (musl_strlen ed (aget (g ed p_kpc) 0)))) 1))
              ^BytePtr buf (BytePtr/alloc len)
              ret (e KEYPROTOCOL_FAIL)
              _ (aset p 0 (aget (g ed p_kpc) 0))]
          (recur 1 term len buf ret prot))
        1
        (if (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) (e NUL))
          (let [ret (e KEYPROTOCOL_NONE)]
            ret)
          (let [_ (long (copy_option_part ed (Ptr. p 0) buf len (BytePtr/lit ",")))
                ^BytePtr colon (vim_strchr ed buf 58)]
            (if (or (or (nil? colon) (BytePtr/eq colon buf)) (== (bit-and (.at colon 1) 0xff) (e NUL)))
              ret
              (let [_ (.put colon (unchecked-byte (e NUL)))]
                (if (== (long (musl_strcmp ed (.add colon 1) (BytePtr/lit "none"))) 0)
                  (let [prot (e KEYPROTOCOL_NONE)]
                    (recur 2 term len buf ret prot))
                  (if (== (long (musl_strcmp ed (.add colon 1) (BytePtr/lit "mok2"))) 0)
                    (let [prot (e KEYPROTOCOL_MOK2)]
                      (recur 2 term len buf ret prot))
                    (if (== (long (musl_strcmp ed (.add colon 1) (BytePtr/lit "kitty"))) 0)
                      (let [prot (e KEYPROTOCOL_KITTY)]
                        (recur 2 term len buf ret prot))
                      ret)))))))
        2
        (let [_ (.zero regmatch)
              _ (.set_rm_ic regmatch (boolean true))
              _ (.set_regprog regmatch (vim_regcomp ed buf (e RE_MAGIC)))]
          (if (nil? (.regprog regmatch))
            ret
            (let [match (and (some? term) (vim_regexec ed regmatch term 0))
                  _ (vim_regfree ed (.regprog regmatch))]
              (if match
                (let [ret prot]
                  ret)
                (recur 1 term len buf ret prot)))))
        (throw (IllegalStateException. "no state"))))))

(defn apply_builtin_tcap [^Editor ed ^BytePtr term ^Ptr entries overwrite]
  (let [^bytes name_ (byte-array 2)]
    (loop [st 0
           ^BytePtr term term
           ^Ptr entries entries
           overwrite overwrite
           term_8bit false
           ^Ptr p nil
           ^BytePtr s nil
           ^BytePtr t nil]
      (case st
        0
        (let [term_8bit (term_is_8bit ed term)
              ^Ptr p entries]
          (recur 1 term entries overwrite term_8bit p s t))
        1
        (if (and (not (== (.bt_entry ^T_tcap_entry_T (.get p)) 0)) (not (== (.bt_entry ^T_tcap_entry_T (.get p)) (e BT_EXTRA_KEYS))))
          (if (>= (.bt_entry ^T_tcap_entry_T (.get p)) 0)
            (if (or (or (nil? (aget (g ed term_strings) (.bt_entry ^T_tcap_entry_T (.get p)))) (BytePtr/eq ^BytePtr (aget (g ed term_strings) (.bt_entry ^T_tcap_entry_T (.get p))) (g ed empty_option))) overwrite)
              (if (and term_8bit (not (== (long (term_7to8bit ed (.bt_string ^T_tcap_entry_T (.get p)))) 0)))
                (let [^BytePtr s (vim_strsave ed (.bt_string ^T_tcap_entry_T (.get p)))
                      ^BytePtr t s]
                  (recur 2 term entries overwrite term_8bit p s t))
                (let [_ (aset (g ed term_strings) (.bt_entry ^T_tcap_entry_T (.get p)) (.bt_string ^T_tcap_entry_T (.get p)))]
                  (recur 3 term entries overwrite term_8bit p s t)))
              (recur 3 term entries overwrite term_8bit p s t))
            (let [_ (aset name_ 0 (unchecked-byte (u8 (bit-and (i32 (- (.bt_entry ^T_tcap_entry_T (.get p)))) 255))))
                  _ (aset name_ 1 (unchecked-byte (u8 (bit-and (bit-shift-right (u32 (i32 (- (.bt_entry ^T_tcap_entry_T (.get p))))) 8) 255))))]
              (if (or (nil? (find_termcode ed (BytePtr. name_ 0))) overwrite)
                (let [_ (add_termcode ed (BytePtr. name_ 0) (.bt_string ^T_tcap_entry_T (.get p)) (if term_8bit 1 0))]
                  (recur 3 term entries overwrite term_8bit p s t))
                (recur 3 term entries overwrite term_8bit p s t))))
          nil)
        2
        (if (zero? (bit-and (.get t) 0xff))
          (let [_ (aset (g ed term_strings) (.bt_entry ^T_tcap_entry_T (.get p)) s)
                _ (long (set_term_option_alloced ed (Ptr. (g ed term_strings) (.bt_entry ^T_tcap_entry_T (.get p)))))]
            (recur 3 term entries overwrite term_8bit p s t))
          (do (if (zero? (long (term_7to8bit ed t)))
                nil
                (let [_ (.put t (unchecked-byte (u8 (long (term_7to8bit ed t)))))
                      _ (Rt/memmove (.add t 1) (.add t 2) (+ (long (musl_strlen ed (.add t 2))) 1))]
                  nil))
            (let [^BytePtr t (.add t 1)]
              (recur 2 term entries overwrite term_8bit p s t))))
        3
        (let [^Ptr p (.add p 1)]
          (recur 1 term entries overwrite term_8bit p s t))
        (throw (IllegalStateException. "no state"))))))

(defn accept_modifiers_for_function_keys [^Editor ed]
  (let [^T_regmatch_T regmatch (new-T_regmatch_T)]
    (let [_ (.zero regmatch)
          _ (.set_rm_ic regmatch (boolean true))
          _ (.set_regprog regmatch (vim_regcomp ed (BytePtr/lit "^\033[\\d\\+\\~$") (e RE_MAGIC)))
          i 0]
      (loop [i i]
        (if (< i (g ed tc_len))
          (if (nil? (.regprog regmatch))
            nil
            (do (if (and (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 0) 0xff) 80) (or (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 1) 0xff) 83) (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 1) 0xff) 69)))
                  nil
                  (let [^BytePtr s (.code ^S_termcode (.at (g ed termcodes) i))]
                    (if (and (some? s) (vim_regexec ed regmatch s 0))
                      (let [len (long (musl_strlen ed s))
                            ^BytePtr ns_ (BytePtr/alloc (+ len 3))
                            _ (Rt/memmove ns_ s (- len 1))
                            _ (Rt/memmove (.add (.add ns_ len) (- 1)) (BytePtr/lit ";*~") 4)
                            _ (.set_code ^S_termcode (.at (g ed termcodes) i) ns_)
                            _ (.set_len ^S_termcode (.at (g ed termcodes) i) (i32 (+ (.len ^S_termcode (.at (g ed termcodes) i)) 2)))
                            _ (adjust_modlen ed i)]
                        nil)
                      nil)))
              (let [i (i32 (inc i))]
                (recur i))))
          (let [_ (vim_regfree ed (.regprog regmatch))]
            nil))))))

(defn apply_keyprotocol [^Editor ed ^BytePtr term ^long prot]
  (do (if (== prot (e KEYPROTOCOL_KITTY))
        (let [_ (apply_builtin_tcap ed term (Ptr. (g ed builtin_kitty) 0) true)]
          nil)
        nil)
    (do (if (== prot (e KEYPROTOCOL_MOK2))
          (let [_ (apply_builtin_tcap ed term (Ptr. (g ed builtin_mok2) 0) true)]
            nil)
          nil)
      (if (== prot (e KEYPROTOCOL_NONE))
        nil
        (let [_ (accept_modifiers_for_function_keys ed)]
          nil)))))

