      (if (or (or (not (== x2 58)) (== x3 -1)) (and (not (== (bit-and (.get p) 0xff) (e NUL))) (not (== (bit-and (.get p) 0xff) 44))))
        (BytePtr. (g ed e_invalid_argument) 0)
        (if (== (bit-and (.get p) 0xff) (e NUL))
