(defn deathtrap [^Editor ed ^long sigarg]
  (loop [st 0
         sigarg sigarg
         i 0]
    (case st
      0
      (if (and (and (== (g ed deathtrap_entered) 0) (or (== sigarg (e SIGHUP)) (== sigarg (e SIGTERM)))) (not (vim_handle_signal ed sigarg)))
        nil
        (let [_ (g! ed deathtrap_entered (i32 (inc (g ed deathtrap_entered))))
              _ (block_autocmds ed)
              _ (g! ed v_dying (g ed deathtrap_entered))
              i 0]
          (recur 1 sigarg i)))
      1
      (if (== (.sig ^S_signalinfo (aget (g ed signal_info) i)) -1)
        (recur 2 sigarg i)
        (if (== sigarg (.sig ^S_signalinfo (aget (g ed signal_info) i)))
          (recur 2 sigarg i)
          (let [i (i32 (inc i))]
            (recur 1 sigarg i))))
      2
      (let [_ (g! ed full_screen (e FALSE))]
        (do (if (== (g ed deathtrap_entered) 2)
              (let [_ (out_str ed (BytePtr/lit "Vim: Double signal, exiting\n"))
                    _ (out_flush ed)
                    _ (getout ed 1)]
                nil)
              nil)
          (let [_ (long (whim.cljhost/vim_snprintf ed (g ed IObuff) 1025 (BytePtr/lit "Vim: Caught deadly signal %s\015\n") (object-array [(.name_ ^S_signalinfo (aget (g ed signal_info) i))])))
                _ (preserve_exit ed)]
            nil)))
      (throw (IllegalStateException. "no state")))))

