                (recur 7 eap i n j p yb name_ attr arg type_ do_show t1)
                (let [^T_yankreg_T yb (if (== i -1)
                                       (if (some? (g ed y_previous))
                                         (let [^T_yankreg_T yb (g ed y_previous)]
