                  (let [_ (msg_puts ed (BytePtr/lit "\n  c  \"/   "))
                        _ (dis_msg ed (last_search_pat ed) false)]
                    (let [_ (g! ed silence_w23_w24_msg (i32 (dec (g ed silence_w23_w24_msg))))]
                      nil))
                  (let [_ (g! ed silence_w23_w24_msg (i32 (dec (g ed silence_w23_w24_msg))))]
                    nil))))))
        2
        (if (and (not do_show) (< j (.y_size yb)))
          (let [do_show (not (message_filtered ed (aget ^objects (.-string ^T_string_T (.at ^Ptr (.y_array yb) j)) 0)))]
            (let [j (inc j)]
