                  _ (msg_putchar ed type_)
                  _ (msg_puts ed (BytePtr/lit "  "))
                  _ (msg_putchar ed 34)
                  _ (msg_putchar ed name_)
                  _ (msg_puts ed (BytePtr/lit "   "))
                  n (i32 (- (i32 (aget (g ed Columns) 0)) 11))
                  j 0]
              (recur 3 eap i n j p yb name_ attr arg type_ do_show t1))
            (recur 4 eap i n j p yb name_ attr arg type_ do_show t1)))
        3
        (if (and (< j (.y_size yb)) (> n 1))
