(defn ex_undolist [^Editor ed ^S_exarg eap]
  (let [^S_growarray ga (new-S_growarray)]
    (loop [st 0
           ^S_u_header uhp nil
           mark 0
           nomark 0
           changes 0
           i 0]
      (case st
        0
        (let [changes 1
              _ (g! ed lastmark (i32 (inc (g ed lastmark))))
              mark (g ed lastmark)
              _ (g! ed lastmark (i32 (inc (g ed lastmark))))
              nomark (g ed lastmark)
