              ^S_u_header uhp (.b_u_oldhead (g ed curbuf))]
          (recur 1 uhp mark nomark changes i))
        1
        (if (some? uhp)
          (if (and (and (nil? (.uh_prev uhp)) (not (== (.uh_walk uhp) nomark))) (not (== (.uh_walk uhp) mark)))
            (if (ga_grow ed ga 1)
              (let [len (long (whim.cljhost/vim_snprintf ed (g ed IObuff) 1025 (BytePtr/lit "%6ld %7d  ") (object-array [(Long/valueOf (.uh_seq uhp)) (Integer/valueOf (unchecked-int changes))])))
                    _ (add_time ed (.add (g ed IObuff) len) (i32 (- 1025 len)) (.uh_time uhp))
                    t1 (i32 (long (musl_strlen ed (.add (g ed IObuff) len))))
                    len (i32 (+ len t1))]
                (let [len (if (> (.uh_save_nr uhp) 0)
                           (let [n (if (>= len 33) 0 (i32 (- 33 len)))
                                 t2 (long (whim.cljhost/vim_snprintf ed (.add (g ed IObuff) len) (i32 (- 1025 len)) (BytePtr/lit "%*.*s  %3ld") (object-array [(Integer/valueOf (unchecked-int n)) (Integer/valueOf (unchecked-int n)) (BytePtr/lit " ") (Long/valueOf (.uh_save_nr uhp))])))
                                 len (i32 (+ len t2))]
                             len)
                           len)]
                  (let [t3 (.ga_len ga)
                        _ (.set_ga_len ga (i32 (inc (.ga_len ga))))
                        _ (.set (GA_Ptr_BytePtr ga) t3 (vim_strnsave ed (g ed IObuff) len))]
                    (recur 2 uhp mark nomark changes i))))
              (recur 4 uhp mark nomark changes i))
            (recur 2 uhp mark nomark changes i))
          (recur 4 uhp mark nomark changes i))
        2
        (let [_ (.set_uh_walk uhp mark)]
          (if (and (and (some? (.uh_prev uhp)) (not (== (.uh_walk ^S_u_header (.uh_prev uhp)) nomark))) (not (== (.uh_walk ^S_u_header (.uh_prev uhp)) mark)))
            (let [^S_u_header uhp (.uh_prev uhp)
                  changes (i32 (inc changes))]
              (recur 3 uhp mark nomark changes i))
            (if (and (and (some? (.uh_alt_next uhp)) (not (== (.uh_walk ^S_u_header (.uh_alt_next uhp)) nomark))) (not (== (.uh_walk ^S_u_header (.uh_alt_next uhp)) mark)))
              (let [^S_u_header uhp (.uh_alt_next uhp)]
                (recur 3 uhp mark nomark changes i))
              (if (and (and (and (some? (.uh_next uhp)) (nil? (.uh_alt_prev uhp))) (not (== (.uh_walk ^S_u_header (.uh_next uhp)) nomark))) (not (== (.uh_walk ^S_u_header (.uh_next uhp)) mark)))
                (let [^S_u_header uhp (.uh_next uhp)
                      changes (i32 (dec changes))]
                  (recur 3 uhp mark nomark changes i))
                (let [_ (.set_uh_walk uhp nomark)]
                  (if (some? (.uh_alt_prev uhp))
                    (let [^S_u_header uhp (.uh_alt_prev uhp)]
                      (recur 3 uhp mark nomark changes i))
                    (let [^S_u_header uhp (.uh_next uhp)
                          changes (i32 (dec changes))]
                      (recur 3 uhp mark nomark changes i))))))))
        3
        (recur 1 uhp mark nomark changes i)
        4
        (if (== (.ga_len ga) 0)
          (let [_ (long (msg ed (gettext_ ed (BytePtr/lit "Nothing to undo"))))]
            nil)
          (let [_ (sort_strings ed (GA_Ptr_BytePtr ga) (.ga_len ga))
                _ (msg_start ed)
                _ (msg_puts_attr ed (gettext_ ed (BytePtr/lit "number changes  when               saved")) (long (aget (g ed highlight_attr) 22)))
                i 0]
            (recur 5 uhp mark nomark changes i)))
        5
        (if (and (< i (.ga_len ga)) (zero? (g ed got_int)))
          (let [_ (msg_putchar ed 10)]
            (if (zero? (g ed got_int))
              (let [_ (msg_puts ed (.at (GA_Ptr_BytePtr ga) i))]
                (let [i (i32 (inc i))]
                  (recur 5 uhp mark nomark changes i)))
              (recur 6 uhp mark nomark changes i)))
          (recur 6 uhp mark nomark changes i))
        6
        (let [_ (msg_end ed)
              _ (ga_clear_strings ed ga)]
