(defn main_loop [^Editor ed cmdwin]
  (let [^S_oparg_S oa (new-S_oparg_S)]
    (let [^S_oparg_S prev_oap (g ed current_oap)
          _ (g! ed current_oap oa)
          _ (clear_oparg ed oa)]
      (loop []
        (if cmdwin
          (let [_ (g! ed current_oap prev_oap)]
            nil)
          (do (if (stuff_empty ed)
                (do (if (zero? (g ed need_wait_return))
                      nil
                      (let [_ (wait_return ed (e FALSE))]
                        nil))
                  (if (and (and (not (zero? (g ed need_start_insertmode))) (goto_im ed)) (zero? (g ed VIsual_active)))
                    (let [_ (g! ed need_start_insertmode (e FALSE))
                          _ (stuffReadbuff ed (BytePtr/lit "i"))
                          _ (g! ed need_fileinfo (e FALSE))]
                      nil)
                    nil))
                nil)
            (do (if (zero? (g ed got_int))
                  nil
                  (do (if (zero? (g ed quit_more))
                        (let [_ (long (vgetc ed))]
                          nil)
                        nil)
                    (let [_ (g! ed got_int (e FALSE))]
                      nil)))
              (let [_ (g! ed msg_scroll (e FALSE))
                    _ (g! ed quit_more (e FALSE))]
                (do (if (zero? (g ed skip_redraw))
                      (if (or (not (zero? (g ed do_redraw))) (stuff_empty ed))
                        (let [_ (may_trigger_deferred_events ed)
                              _ (may_trigger_safestate ed (and (not (op_pending ed)) (== (g ed restart_edit) 0)))
                              _ (update_topline ed)
                              _ (validate_cursor ed)]
                          (do (if (zero? (g ed VIsual_active))
                                (if (zero? (g ed must_redraw))
                                  (if (or (or (not (zero? (g ed redraw_cmdline))) (not (zero? (g ed clear_cmdline)))) (not (zero? (g ed redraw_mode))))
                                    (let [_ (long (showmode ed))]
                                      nil)
                                    nil)
                                  (let [_ (update_screen ed 0)]
                                    nil))
                                (let [_ (update_curbuf ed (e UPD_INVERTED))]
                                  nil))
                            (let [_ (redraw_statuslines ed)]
                              (do (if (some? (g ed keep_msg))
                                    (let [^BytePtr p (vim_strsave ed (g ed keep_msg))
                                          _ (g! ed msg_hist_off (e TRUE))
                                          _ (long (msg_attr ed p (g ed keep_msg_attr)))
                                          _ (g! ed msg_hist_off (e FALSE))]
                                      nil)
                                    nil)
                                (do (if (zero? (g ed need_fileinfo))
                                      nil
                                      (let [_ (fileinfo ed (e FALSE) true false)
                                            _ (g! ed need_fileinfo (e FALSE))]
                                        nil))
                                  (let [_ (g! ed emsg_on_display (e FALSE))
                                        _ (g! ed did_emsg (e FALSE))
                                        _ (g! ed msg_didany (e FALSE))
                                        _ (may_clear_sb_text ed)
                                        _ (showruler ed false)
                                        _ (setcursor ed)
                                        _ (cursor_on ed)
                                        _ (g! ed do_redraw (e FALSE))
                                        _ (may_make_initial_scroll_size_snapshot ed)]
                                    nil))))))
                        nil)
                      (let [_ (g! ed skip_redraw (e FALSE))
                            _ (setcursor ed)
                            _ (cursor_on ed)]
                        nil))
                  (let [_ (may_send_t_RK ed)
                        _ (update_curswant ed)
                        _ (normal_cmd ed oa true)]
                    (recur)))))))))))

(defn vim_main2 ^long [^Editor ed]
  (let [_ (g! ed starting (e NO_BUFFERS))
        _ (g! ed no_wait_return (e FALSE))
        _ (g! ed msg_scroll (e FALSE))]
    (do (if (and (or (not (zero? (g ed did_emsg))) (not (zero? (g ed msg_didout)))) (not (== (bit-and (.get ^BytePtr (aget (g ed term_strings) 42)) 0xff) (e NUL))))
          (let [_ (g! ed newline_on_exit (e TRUE))]
            nil)
          nil)
      (let [_ (term_enter ed)]
        (do (if (or (not (zero? (g ed need_wait_return))) (not (zero? (g ed msg_didany))))
              (let [_ (wait_return ed (e TRUE))]
                nil)
              nil)
          (let [_ (starttermcap ed)]
            (do (if (zero? (g ed scroll_region))
                  nil
                  (let [_ (scroll_region_reset ed)]
                    nil))
              (let [_ (scroll_start ed)
                    _ (screenclear ed)
                    _ (g! ed no_wait_return (e TRUE))
                    _ (create_windows ed (g ed params))
                    _ (setpcmark ed)
                    _ (shorten_fnames ed)]
                (do (if (> (.n_commands (g ed params)) 0)
                      (let [_ (exe_commands ed (g ed params))]
                        nil)
                      nil)
                  (let [_ (g! ed starting 0)
                        _ (g! ed RedrawingDisabled 0)
                        _ (redraw_all_later ed (e UPD_NOT_VALID))
                        _ (g! ed no_wait_return (e FALSE))]
                    (do (if (zero? (long (aget (g ed p_im) 0)))
                          nil
                          (let [_ (g! ed need_start_insertmode (e TRUE))]
                            nil))
                      (if (== (g ed restart_edit) 0)
                        (let [_ (g! ed do_redraw (e TRUE))
                              _ (main_loop ed false)]
                          0)
                        (let [_ (stuffcharReadbuff ed (e K_NOP))]
                          (let [_ (g! ed do_redraw (e TRUE))
                                _ (main_loop ed false)]
                            0))))))))))))))

