(defn mainerr [^Editor ed ^long n ^BytePtr str_]
  (let [^bytes buf (byte-array 1024)]
    (let [_ (init_longVersion ed)]
      (if (some? str_)
        (let [_ (long (whim.cljhost/vim_snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s: \"%s\"") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main_errors) n)) str_])))]
          (let [_ (whim.cljhost/host_message ed (BytePtr. buf 0) -1 (e TRUE))
                _ (mch_exit ed 1)]
            nil))
        (let [_ (long (whim.cljhost/vim_snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main_errors) n))])))]
          (let [_ (whim.cljhost/host_message ed (BytePtr. buf 0) -1 (e TRUE))
                _ (mch_exit ed 1)]
            nil))))))

(defn command_line_scan [^Editor ed ^T_mparm_T parmp]
  (loop [st 0
         ^T_mparm_T parmp parmp
         argc 0
         ^Ptr argv nil
         argv_idx 0]
    (case st
      0
      (let [argc (.argc parmp)
            ^Ptr argv (.argv parmp)
            argc (i32 (dec argc))
            ^Ptr argv (.add argv 1)
            argv_idx 1]
        (recur 1 parmp argc argv argv_idx))
      1
      (if (> argc 0)
        (let [argv_idx (if (== (long (.at ^BytePtr (.at argv 0) 0)) 43)
                        (do (if (>= (.n_commands parmp) (e MAX_ARG_CMDS))
                              (let [_ (mainerr ed (e ME_EXTRA_CMD) nil)]
                                nil)
                              nil)
                          (let [argv_idx -1]
                            (if (== (long (.at ^BytePtr (.at argv 0) 1)) (e NUL))
                              (let [t1 (.n_commands parmp)
                                    _ (.set_n_commands parmp (i32 (inc (.n_commands parmp))))
                                    _ (aset ^objects (.-commands parmp) t1 (BytePtr/lit "$"))]
                                argv_idx)
                              (let [t2 (.n_commands parmp)
                                    _ (.set_n_commands parmp (i32 (inc (.n_commands parmp))))
                                    _ (aset ^objects (.-commands parmp) t2 (.add ^BytePtr (.at argv 0) 1))]
                                argv_idx))))
                        (let [_ (mainerr ed (e ME_UNKNOWN_OPTION) (.at argv 0))]
                          argv_idx))]
          (if (or (<= argv_idx 0) (== (long (.at ^BytePtr (.at argv 0) argv_idx)) (e NUL)))
            (let [argc (i32 (dec argc))
                  ^Ptr argv (.add argv 1)
                  argv_idx 1]
              (recur 2 parmp argc argv argv_idx))
            (recur 2 parmp argc argv argv_idx)))
        nil)
      2
      (recur 1 parmp argc argv argv_idx)
      (throw (IllegalStateException. "no state")))))

(defn vim_main ^long [^Editor ed ^long argc ^Ptr argv]
  (let [_ (.zero (g ed params))
        _ (.set_argc (g ed params) argc)
        _ (.set_argv (g ed params) argv)
        _ (.set_want_full_screen (g ed params) (boolean true))
        _ (common_init_1 ed)
        _ (common_init_2 ed (g ed params))
        _ (command_line_scan ed (g ed params))
        _ (g! ed RedrawingDisabled (i32 (inc (g ed RedrawingDisabled))))
        _ (mch_init ed)]
    (do (if (.want_full_screen (g ed params))
          (let [_ (termcapinit ed)
                _ (screen_start ed)]
            nil)
          nil)
      (let [_ (ui_get_shellsize ed)
            _ (win_init_size ed)
            _ (g! ed cmdline_row (i32 (- (aget (g ed Rows) 0) (aget (g ed p_ch) 0))))
            _ (g! ed cmdline_col_off 0)
            _ (g! ed cmdline_width (i32 (aget (g ed Columns) 0)))
            _ (g! ed msg_row (g ed cmdline_row))
            _ (g! ed msg_col 0)
            _ (screenalloc ed false)
            _ (set_init_2 ed)
            _ (g! ed msg_scroll (e TRUE))
            _ (g! ed no_wait_return (e TRUE))
            _ (init_mappings ed)
            _ (init_highlight ed true false)]
        (long (vim_main2 ed))))))

